INSERT INTO m247_art VALUES
(0,0,$m247$الديباجة$m247$,$m247$قانون رقم 49 لسنة 1977 فى شأن تأجير وبيع الأماكن وتنظيم العلاقة بين المؤجر والمستأجر
باسم الشعب
رئيس الجمهورية
قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m247$,'61ced0d78da8c78beadcce60973c52ee'),
(1,0,$m247$المادة 1$m247$,$m247$فيما عدا الأراضى الفضاء تسرى أحكام هذا الباب على الأماكن وأجزاء الأماكن على اختلاف أنواعها المعدة للسكنى أو لغير ذلك من الأغراض سواء كانت مفروشة أو غير مفروشة مؤجرة من المالك أو من غيره وذلك فى عواصم المحافظات والبلاد المعتبرة مدنا بالتطبيق لأحكام القانون رقم 52 لسنة 1975 بإصدار قانون نظام الحكم المحلى والقوانين المعدلة له .
ويجوز بقرار من وزير الإسكان والتعمير مد نطاق سريان أحكامه كلها أو بعضها على القرى بناء على اقتراح المجلس المحلى للمحافظة وكذلك على المناطق السكنية التى لا ينطبق عليها قانون نظام الحكم المحلى المشار إليه ، ولا يكون لهذا القرار أثر على الأجرة المتعاقد عليها قبل صدوره .$m247$,'75ad3fc0e09a032822d8aaea92d0b672'),
(2,0,$m247$المادة 2$m247$,$m247$لا تسرى أحكام هذا الباب على :
(أ) المساكن الملحقة بالمرافق والمنشآت وغيرها من المساكن التى تشغل بسبب العمل .
(ب) المساكن التى تشغل بتصاريح أشغال مؤقتة لمواجهة حالات الطوارئ والضرورة ويصدر تحديد تلك الحالات وشروط الانتفاع بهذه المساكن قرار من وزير الإسكان والتعمير .$m247$,'7802921828e5386f6ec618e3cb4915c2'),
(3,0,$m247$المادة 3$m247$,$m247$يحظر على المرخص لهم فى إقامة مبان أو أجزاء منها من المستوى الفاخر ، الاستفادة من النظم أو الميزات الخاصة بتوزيع أو صرف أو تيسير الحصول على مواد البناء .
ويتولى ملاك هذه المبانى بمعرفتهم وعلى نفقتهم استيراد ما يلزم لها من مواد البناء أو شرائها من المواد المستوردة أو من المواد المنتجة محليا بالأسعار العالمية بعد الوفاء باحتياجات المستويات الأخرى من الإسكان .$m247$,'15a254b3d8588cec64e6a338f74559b3'),
(4,0,$m247$المادة 4$m247$,$m247$تسرى أحكام هذا الباب على الأماكن التى ينشئها ، اعتبارا من تاريخ العمل بهذا القانون ، مستأجرو الأراضى الفضاء على هذه الأراضى بترخيص كتابى من مالكها متى توافرت الشروط الآتية :
(أ) أن يكون الترخيص تاليا لتاريخ العمل بهذا القانون .
(ب) أن تكون المبانى شاغلة لنسبة مقدارها خمسون فى المائة (50%) على الأقل من الحد الأقصى المسموح بالارتفاع به مسطحا وارتفاعا وفقا لأحكام قانون توجيه وتنظيم أعمال البناء .
(ج) ألا يقل مسطح المبانى المخصصة للسكنى عن ثلاثة أرباع مجموع مسطحات المبانى .
وإذا انتهى عقد إيجار الأرض الفضاء لأى سبب من الأسباب استمر من أنشأ الأماكن المقامة عليها أو من استأجرها منه بحسب الأحوال شاغلا لهذه الأماكن بالأجرة المحددة قانونا .$m247$,'d83221227320a3dc2ed74ca1299d6725'),
(5,0,$m247$المادة 5$m247$,$m247$تختص المحاكم العادية دون غيرها بالفصل فى المنازعات التى تنشأ عن تطبيق أحكام هذا القانون .$m247$,'8846c3000b3d6b6d5ec7fe281e19bdb6'),
(6,0,$m247$المادة 6$m247$,$m247$يعد فى حكم المستأجر فى تطبيق أحكام هذا الباب مالك العقار المنزوعة ملكيته بالنسبة إلى ما يشغله من هذا العقار .
وتعتبر الأماكن الصادر فى شأنها قرارات استيلاء لشغلها مؤجرة إلى الجهات التى تم الاستيلاء لصالحها .$m247$,'dbd7a590af4069c5386a8bea0bf863ac'),
(7,0,$m247$المادة 7$m247$,$m247$للعامل المنقول إلى بلد بدلا من عامل آخر فى ذات جهة العمل حق الأولوية على غيره فى استئجار المسكن الذى كان يشغله هذا العامل إذا قام بإعلان المؤجر فى مدى أسبوعين على الأكثر من تاريخ الإخلاء برغبته فى ذلك بكتاب موصى عليه مصحوب بعلم الوصول على أن يعزز ذلك عن طريق الجهة التى يعمل بها المتبادلان ، ويحظر على المالك التعاقد قبل انقضاء هذه المدة .
وعلى العامل المنقول إلى بلد آخر أن يخلى المسكن الذى كان يشغله بمجرد حصوله على مسكن فى البلد المنقول إليه ، إلا إذا قامت ضرورة ملجئة تمنع من إخلاء مسكنه .
وفى البلد الواحد يجوز تبادل الوحدات السكنية بين مستأجر وآخر وذلك […] البلاد و بين الأحياء ، وطبقا للحالات ووفقا للقواعد والشروط والإجراءات والضمانات التى يحددها قرار من وزير الإسكان والتعمير .$m247$,'cfc3ffbb06499a265c4b185708e3792e'),
(8,0,$m247$المادة 8$m247$,$m247$لا يجوز للشخص أن يحتجز فى البلد الواحد أكثر من مسكن بلا مقتض .
ولا يجوز إبقاء المساكن المعدة للاستغلال خالية مدة تزيد على أربعة أشهر إذا قدم لاستئجارها مستأجر بالأجرة القانونية .
ويعتبر فى حكم إبقاء المساكن خالية التراخى عمدا عن إعدادها للاستغلال ، وفى هذه الحالة يجوز للمحافظ المختص التنبيه على المالك بكتاب موصى عليه بعلم وصول لإعداد البناء للاستغلال فى المهلة التى يحددها له ، فإذا انقضت هذه المهلة دون ذلك كان للمحافظ أن يعهد إلى إحدى الجهات القيام بإعداد البناء للاستغلال على حساب المالك وفقا للقواعد التى يصدر بها قرار من وزير الإسكان والتعمير ، ويكون للمبالغ المستحقة لهذه الجهة حق امتياز على المبنى الذى قامت باستكماله من ذات مرتبة الامتياز المقرر بالمادة (1148) من القانون المدنى .
ويكون للجهة المشار إليها تأجير وحدات المبنى التى لم يسبق تأجيرها واقتضاء أجرة وحدات المبنى جميعه إلى أن تستوفى المبالغ التى أنفقتها والمصروفات الإدارية ، ويحق للمالك أن يحصل على 20% من تلك الأجرة شهريا .$m247$,'fd0810c0d62bdfc46a1177b6fbb452e7'),
(9,0,$m247$المادة 9$m247$,$m247$يستمر العمل بالأحكام المحددة للأجرة والأحكام المقررة على مخالفتها بالقانون رقم 121 لسنة 1947 بشأن إيجار الأماكن وتنظيم العلاقات بين المؤجرين والمستأجرين والقانون رقم 169 لسنة 1961 بتقرير بعض الإعفاءات من الضريبة على العقارات المبنية وخفض الإيجارات بمقدار الاعفاءات ، والقانون رقم 46 لسنة 1962 بتحديد إيجار الأماكن والقانون رقم 7 لسنة 1965 فى شأن تخفيض إيجار الأماكن والقانون رقم 52 لسنة 1969 فى شأن إيجار الأماكن وتنظيم العلاقة بين المؤجرين والمستأجرين والقوانين المعدلة لها ، وذلك بالنسبة إلى نطاق سريان كل منها .$m247$,'4e1f76b753697758c77ae4c1bd9776c7'),
(10,0,$m247$المادة 10$m247$,$m247$يجب على من يرغب فى إقامة مبنى أن يرفق بطلب الترخيص له بالبناء المقدم إلى الجهة الإدارية المختصة بشئون التنظيم بيانا بقيمة الأرض والمبانى ومواصفات البناء ومقترحاته عن أجرة المبنى وتوزيعها على وحداته وما يدل على أداء مبلغ 500 قرش عن كل وحدة من هذه الوحدات ، ويحتسب هذا المبلغ ضمن تكاليف المبنى وتخصص حصيلة هذا المبلغ للاتفاق منه على أغراض لجنة تحديد الإيجارات أو الطعن فى قراراتها وفقا للنظام الذى يصدر به قرار من وزير الإسكان والتعمير .
وتكون البيانات المشار إليها والموضحة باللائحة التنفيذية متممة للمستندات اللازمة للحصول على الترخيص المشار إليه طبقا لأحكام القانون رقم 106 لسنة 1976 فى شأن توجيه وتنظيم أعمال البناء والقرارات المنفذة له .$m247$,'3d789e804e73dc6a90e73d2ad631938c'),
(11,0,$m247$المادة 11$m247$,$m247$يتضمن قرار الجهة الإدارية المختصة بشئون التنظيم بالموافقة على إقامة البناء تقدير الأجرة الإجمالية للمبنى وفقا للأحكام الواردة فى هذا الباب وتوزيعها على وحدات المبنى وصرف ترخيص البناء موضحا به قرار التقدير والتوزيع وعلى أساسه يتم التعاقد بين المؤجر والمستأجر على أن يتم تحديد الأجرة طبقا لأحكام هذا الباب .
ويكون التقدير المبدئى للأجرة وفقا للقرارات التى يصدرها وزير الإسكان والتعمير فى شأن تحديد مستويات ومواصفات المبانى وأسس تكاليفها التقديرية وفقا لأحكام القانون رقم 106 لسنة 1976$m247$,'6aae77f9a3dfaebe9930eb66b0e525b6'),
(12,0,$m247$المادة 12$m247$,$m247$تتولى تحديد أجرة الأماكن الخاضعة لأحكام هذا القانون وتوزيعها على وحداته لجان يصدر بتشكيلها قرار من المحافظ المختص من اثنين من المهندسين المعماريين أو المدنيين المقيدين بنقابة المهندسين ومن جهتين مختلفتين وأحد العاملين المختصين بربط أو تحصيل الضريبة على العقارات المبنية وعضوين يختارهما المجلس المحلى المختص من غير أعضائه أحدهما من الملاك والآخر من المستأجرين ، وتكون رئاستها للأقدم من المهندسين ، ويشترط لصحة انعقادها حضور أحد المهندسين والعضو المختص بربط أو تحصيل الضريبة وأحد العضوين المختارين ، وتصدر قرارات اللجنة بأغلبية أصوات الحاضرين وعند التساوى يرجح رأى الجانب الذى منه الرئيس .
ويؤدى أعضاء اللجان قبل مباشرة أعمالهم يمينا أمام المحافظ بأن يؤدوا أعمالهم بصدق وأمانة .
ويصدر وزير الإسكان والتعمير قرارا بالقواعد والإجراءات التى تنظم أعمال هذه اللجان وطريقة إخطار ذوى الشأن بقراراتها الصادرة فى شأن تحديد الأجرة .$m247$,'75f0c6cfe2ff009eade69e4203b081dd'),
(13,0,$m247$المادة 13$m247$,$m247$على مالك البناء فى موعد لا يجاوز ثلاثين يوما من تاريخ نفاذ أول عقد لإيجار أية وحدة من وحدات المبنى أو من تاريخ شغلها لأول مرة بأية صورة من صور الأشغال أن يخطر اللجنة المشار إليها فى المادة السابقة والتى يقع فى دائرتها المبنى لتقوم بتحديد أجرته وتوزيعها على وحداته بعد مراجعة ما تم إنجازه ومطابقته للمواصفات الصادر على أساسها موافقة لجنة توجيه استمارات أعمال البناء ، وترخيص المبانى .
وللمستأجر أن يخطر اللجنة المذكورة بشغله المكان المؤجر بكتاب موصى عليه .
وتنظم اللائحة التنفيذية إجراءات إخطار المالك والمستأجر للجنة .
ويجوز للجنة أن تقوم بالتقدير من تلقاء نفسها أو بناء على إخطار من الجهة المختصة بحصر العقارات المبنية .
ويلتزم المالك بتسليم العين المؤجرة صالحة للاستعمال فى المواعيد المتفق عليها وإلا جاز للمستأجر بعد إعذار المالك استكمال الأعمال الناقصة بترخيص من قاضى الأمور المستعجلة مع خصم التكاليف من الأجرة .$m247$,'e14f869f9a40fcf8a3211a457b1502bb'),
(14,0,$m247$المادة 14$m247$,$m247$تقدر أجرة المبنى المرخص فى إقامته من تاريخ العمل بهذا القانون على الأسس التالية :
(أ) صافى عائد استثمار العقار بواقع 7% (سبعة فى المائة) من قيمة الأرض والمبانى .
(ب) مقابل استهلاك رأس المال ومصروفات الإصلاحات والصيانة والإدارة بواقع 3% (ثلاثة فى المائة) من قيمة المبانى .
ومع مراعاة الإعفاءات المقررة فى شأن الضريبة على العقارات المبنية يضاف إلى الأجرة المحددة وفقا لما تقدم ما يخصها من الضرائب العقارية الأصلية والإضافية كل ذلك مع عدم الإخلال بأحكام القوانين الأخرى الخاصة بالتزامات كل من المؤجرين والمستأجرين بشأن الضرائب والرسوم .
ويلتزم المستأجر بأداء هذه الضرائب والرسوم إلى المؤجر مع الأجرة الشهرية ويترتب على عدم الوفاء بها نفس النتائج المترتبة على عدم سداد الأجرة .$m247$,'c738f8f5a608e005087d81001668ae9c'),
(15,0,$m247$المادة 15$m247$,$m247$يكون تحديد أجرة المبانى بعد إنشائها على أساس تقدير قيمة الأرض وفقا لثمن المثل فى عام 1974 مع زيادة سنوية مقدارها 7% (سبعة فى المائة) لحين البناء ، وتقدير قيمة المبانى وفقا للتكلفة الفعلية وقت البناء ، وذلك دون التقيد بالأجرة المبدئية المقدرة للمبنى قبل إنشائه مع الالتزام بمستوى المبانى المبين بالموافقة الصادر على أساسها ترخيص البناء ودون اعتداد بأية زيادة فى المواصفات أثناء التنفيذ .
وتحسب كامل قيمة الأرض والمبانى والأساسات والتوصيلات الخارجية للمرافق العامة فى حالة البناء على كل المساحة المسموح بالبناء عليها واستيفاء الارتفاع طبقا للقيود المفروضة على المنطقة وأحكام قانون توجيه وتنظيم أعمال البناء وغيره من القوانين واللوائح .
أما فى حالة البناء على كل المساحة المسموح بالبناء عليها مع عدم استكمال المبنى الحد الأقصى المسموح به لارتفاع البناء تحسب كل قيمة المبانى المنشأة كما تحسب قيمة الأرض والأساسات والتوصيلات الخارجية للمرافق بنسبة ما يقام فعلا من أدوار إلى العدد الكلى للأدوار التى تسمح بها قيود الارتفاع المشار إليها ، ويجوز فى بعض المناطق تعديل هذه النسبة بما يتفق وصقع الموقع وظروف العمران وذلك بقرار من المجلس المحلى المختص .
وإذا كان البناء لا يشغل غير جزء من الأرض المسموح بالبناء عليها فلا يحسب فى تقدير الإيجار من قيمة الأرض إلا القدر المخصص لمنفعة البناء فقط بشرط تحديد هذا القدر بفواصل ثابتة وإلا فلا تحسب سوى المساحة المبنى عليها بالفعل .$m247$,'aa4f571379c510f853ec18c58228712c'),
(16,0,$m247$المادة 16$m247$,$m247$يعاد تقدير قيمة الأرض عند تحديد الأجرة فى حالة تعلية البناء وذلك إذا تمت التعلية بعد سنتين على الأقل من تاريخ إنشاء المبانى الأصلية أو فى حالة ما إذا طرأ على العقار ما يستوجب تطبيق أحكام القوانين السارية فى شأن مقابل التحسين وفى هذه الحالة تكون إعادة تقدير قيمة الأرض بقصد تحديد أجرة المبانى المستجدة فقط .$m247$,'72083910bef5acf2b02901a1b0c359bb'),
(17,0,$m247$المادة 17$m247$,$m247$تكون قرارات لجان تحديد الأجرة نافذة رغم الطعن عليها ، وتعتبر نهائية إذا لم يطعن عليها فى الميعاد .$m247$,'7d35f6d085a944a57620d2415f303070'),
(18,0,$m247$المادة 18$m247$,$m247$يكون الطعن على قرارات لجان تحديد الأجرة خلال ثلاثين يوما من تاريخ الإخطار بصدور قرار اللجنة أمام المحكمة الابتدائية الكائن فى دائرتها المكان المؤجر ويلحق بتشكيلها مهندس معمارى أو مدنى مقيد بنقابة المهندسين من الدرجة الثانية على الأقل ومن غير القائمين بتحديد الأجرة يختاره المحافظ لمدة سنتين قابلة للتجديد ولا يكون له صوت معدود فى المداولة .
ويحلف المهندس يمينا أمام إحدى دوائر الاستئناف المختصة بأن يؤدى عمله بصدق وأمانة .$m247$,'bfb7c2ec9410be213b1089ed71f1d57d'),
(19,0,$m247$المادة 19$m247$,$m247$على قلم كتاب المحكمة إخطار جميع المستأجرين لباقى وحدات المبنى بالطعن وبالجلسة المحددة لنظره وذلك بكتاب موصى عليه مصحوب بعلم الوصول .
ويترتب على قبول الطعن إعادة النظر فى تقدير أجرة باقى الوحدات التى شملها قرار لجنة تحديد الأجرة ويعتبر الحكم الصادر فى الطعن ملزما لكل من المالك والمستأجرين .$m247$,'f84d1a920240cc727c2f255f8f7bd595'),
(20,0,$m247$المادة 20$m247$,$m247$لا يجوز الطعن فى الحكم الصادر من المحكمة المشار إليها فى المادة (18) إلا لخطأ فى تطبيق القانون .
ويكون الطعن أمام محكمة الاستئناف خلال ثلاثين يوما من تاريخ صدور الحكم وذلك بصحيفة تقدم إلى قلم كتاب المحكمة — يوضح بها أسماء الخصوم ومحال إقامتهم وتاريخ الحكم المطعون عليه وأوجه الطعن .
ويكون حكمها غير قابل للطعن فيه بأى وجه من أوجه الطعن .$m247$,'baded39f267e9e7b32e3b60b473ec13e'),
(21,0,$m247$المادة 21$m247$,$m247$إذا لم تكن العين مؤجرة وقت صدور قرار لجنة تحديد الأجرة ، جاز لأول مستأجر لها أن يطعن على هذا القرار خلال ثلاثين يوما من تاريخ نفاذ عقده .
وفى هذه الحالة يقتصر أثر الحكم الصادر فى الطعن على أجرة الوحدة التى يشغلها الطاعن وحدها دون باقى وحدات المبنى .$m247$,'a6d1eb42e239630cf32b40f166dee798'),
(22,0,$m247$المادة 22$m247$,$m247$يلتزم المستأجر فى حالة تحديد الأجرة بالزيادة عما هو منصوص عليه فى العقد ، بأداء الفرق مقسطا على أقساط شهرية لمدة مساوية للمدة التى استحق عنها أو بسداده كاملا إذا أراد إخلاء العين المؤجرة قبل انقضاء المدة المذكورة .
وعلى المؤجر أن يرد إلى المستأجر فرق الأجرة عند تحديدها بما يقل عما هو منصوص عليه فى العقد وبالطريقة المنصوص عليها فى الفقرة السابقة .$m247$,'253259e9130a9f7caaf6005b776a61df'),
(23,0,$m247$المادة 23$m247$,$m247$فى جميع الأحوال التى يتم فيها تغيير استعمال العين المؤجرة بعد تاريخ العمل بهذا القانون وبموافقة المالك إلى غير أغراض السكنى تزاد الأجرة القانونية بنسبة 200% للمبانى المنشأة قبل أول يناير سنة 1944 ، 100% للمبانى المنشأة منذ أول يناير سنة 1944 وقبل 5 نوفمبر سنة 1961 ، 75% للمبانى المنشأة منذ 5 نوفمبر سنة 1961 حتى تاريخ العمل بهذا القانون ، 50% للمبانى التى يرخص فى إقامتها اعتبارا من تاريخ العمل بهذا القانون .$m247$,'489a8c765faf35edbb8449275e654536'),
(24,0,$m247$المادة 24$m247$,$m247$اعتبارا من تاريخ العمل بأحكام هذا القانون تبرم عقود الإيجار كتابة ويجب إثبات تاريخها بمأمورية الشهر العقارى الكائن بدائرتها العين المؤجرة .
ويلزم المؤجر عند تأجير أى مبنى أو وحدة منه أن يثبت فى عقد الإيجار تاريخ ورقم وجهة إصدار ترخيص البناء ومقدار الأجرة المقدرة للوحدة المؤجرة وفقا للمادة (11) من هذا القانون ، وذلك بالنسبة للمبانى الخاضعة لنظام الأجرة المبدئية .
ويجوز للمستأجر إثبات واقعة التأجير وجميع شروط العقد بكافة طرق الإثبات .
ويحظر على المؤجر إبرام أكثر من عقد إيجار واحد للمبنى أو الوحدة منه وفى حالة المخالفة يقع باطلا العقد أو العقود اللاحقة للعقد الأول .$m247$,'617302d81ab6d7b22eee43b74cbe38e3'),
(25,0,$m247$المادة 25$m247$,$m247$لا يجوز أن يزيد مقدار التأمين الذى يدفعه المستأجر على ما يعادل أجرة شهرين ويسرى هذا الحكم على عقود الإيجار القائمة وقت العمل بهذا القانون وللمستأجر الحق فى استرداد الزيادة فى قيمة التأمين بخصمها مباشرة من الأجرة مقسطة على سنة أو حتى نهاية العقد أو عند إخلاء العين المؤجرة أيهما أقرب وذلك بغير حاجة إلى الالتجاء إلى القضاء .$m247$,'7db630cdeaa0353b2aa698fe88e32ba4'),
(26,0,$m247$المادة 26$m247$,$m247$لا يجوز للمؤجر مالكا كان أو مستأجرا بالذات أو بالوساطة اقتضاء أى مقابل أو أتعاب بسبب تحرير العقد أو أى مبلغ إضافى خارج نطاق عقد الإيجار زيادة على التأمين والأجرة المنصوص عليها فى العقد .
كما لا يجوز بأية صورة من الصور للمؤجر أن يتقاضى أى مقدم إيجار .$m247$,'7dc8e761607e4479457f997ff43c4432'),
(27,0,$m247$المادة 27$m247$,$m247$يجب أن يتم الوفاء بالأجرة المحددة وما فى حكمها كاملة إلى المؤجر طبقا لأحكام هذا الباب فى موعد لا يجاوز الأسبوع الأول من الشهر المستحقة عنه أو الموعد المتفق عليه فى العقد وذلك بإيصال مثبتا فيه قيمة الأجرة .
فإذا امتنع المؤجر عن استلام الأجرة وإعطاء سند المخالصة عنها ، فللمستأجر قبل مضى 15 (خمسة عشر) يوما من تاريخ الاستحقاق أن ينذر المؤجر بكتاب موصى عليه مصحوب بعلم وصول لتسلمها خلال أسبوع ، فإذا لم يتسلمها خلال هذا الميعاد يودع المستأجر الأجرة بدون رسوم خلال الأسبوع التالى بخزانة مأمورية العوائد المختصة .
وفى المدن والقرى التى لا توجد بها مأموريات عوائد ، يتم الإيداع بخزينة الوحدة المحلية الواقع فى دائرتها العقار .
وعلى كل من المستأجر والجهة المودع لديها الأجرة إخطار المؤجر بهذا الإيداع بكتاب موصى عليه مصحوب بعلم وصول .
ومع عدم المساس بما يكون للمؤجر من حقوق أخرى يعتبر إيصال الإيداع سندا لإبراء ذمة المستأجر من قيمة الأجرة المستحقة بالقدر المودع .
وعلى الجهة المودع لديها الأجرة أداء الأجرة المودعة للمؤجر فور طلبها دون قيد أو شرط أو إجراءات .$m247$,'bfe7733048bad142ed00f95748bca2fb'),
(28,0,$m247$المادة 28$m247$,$m247$لا يجوز حرمان المستأجر من أى حق من حقوقه أو منعه من أية ميزة كان يتمتع بها .
ولقاضى الأمور المستعجلة أن يأذن للمستأجر فى هذه الحالة بإعادة الحق أو الميزة على حساب المؤجر خصما من الأجرة المستحقة وذلك بعد إعذار المؤجر بإعادتها إلى ما كانت عليه فى وقت مناسب .
ويجوز للجهة التى تحدد بقرار من المحافظ القيام بتنفيذ الأعمال اللازمة لإعادة الحق أو الميزة التى ألزم بها المالك بموجب الحكم الصادر فى هذا الشأن وذلك على نفقة المالك على أن تقتضى النفقات منه بالطريق الإدارى .
ومع ذلك إذا أصبح التزام المؤجر مرهقا أو غير متناسب مع ما يغله العقار من أجرة ، ففى هذه الحالة يجوز للقاضى أن يوزع تكلفة الإعادة على كل من المؤجر والمستأجر .
فإذا تبين عدم إمكان إعادة الحق أو الميزة ، جاز للمحكمة الابتدائية الواقع فى دائرتها العقار بناء على طلب المستأجر إنقاص الأجرة بما يقابل الحق أو الميزة .$m247$,'fbc928d86278754fccc211a857e7df10'),
(29,0,$m247$المادة 29$m247$,$m247$مع عدم الإخلال بحكم المادة (8) من هذا القانون لا ينتهى عقد إيجار المسكن بوفاة المستأجر أو تركه العين إذا بقى فيها زوجه أو أولاده أو أى من والديه الذين كانوا يقيمون معه حتى الوفاة أو الترك وفيما عدا هؤلاء من أقارب المستأجر نسبا أو مصاهرة حتى الدرجة الثالثة يشترط لاستمرار عقد الإيجار إقامتهم فى المسكن مدة سنة على الأقل سابقة على وفاة المستأجر أو تركه العين أو مدة شغله للمسكن أيهما أقل .
إذا كانت العين مؤجرة لمزاولة نشاط تجارى أو صناعى أو مهنى أو حرفى فلا ينتهى العقد بوفاة المستأجر أو تركه العين ويستمر لصالح ورثته وشركائه فى استعمال العين بحسب الأحوال .
وفى جميع الأحوال يلتزم المؤجر بتحرير عقد إيجار لمن لهم حق فى الاستمرار فى شغل العين ويلتزم هؤلاء الشاغلون بطريق التضامن بكافة أحكام العقد .$m247$,'7a38b31403a3ea7502ffb4290234f52a'),
(30,0,$m247$المادة 30$m247$,$m247$استثناء من حكم المادة (604) من القانون المدنى تسرى عقود الإيجار القائمة على المالك الجديد للعقار ولو لم يكن لسند الإيجار تاريخ ثابت بوجه رسمى سابق على تاريخ انتقال الملكية .$m247$,'3e5c291348a91ba96f4a971155468c10'),
(31,0,$m247$المادة 31$m247$,$m247$فى غير الأماكن المؤجرة مفروشة لا يجوز للمؤجر أن يطلب إخلاء المكان ولو انتهت المدة المتفق عليها فى العقد إلا لأحد الأسباب الآتية :
(أ) إذا لم يقم المستأجر بالوفاء بالأجرة المستحقة خلال خمسة عشر يوما من تاريخ تكليفه بذلك بكتاب موصى عليه مصحوب بعلم الوصول دون مظروف أو بإعلان على يد محضر ولا يحكم بالإخلاء إذا قام المستأجر قبل إقفال باب المرافعة فى الدعوى بأداء الأجرة وكافة ما تكبده المؤجر من مصاريف ونفقات فعلية فإذا تكرر امتناع المستأجر أو تأخره فى الوفاء بالأجرة المستحقة دون مبررات تقدرها المحكمة حكم عليه بالإخلاء .
ولا ينفذ حكم القضاء المستعجل بطرد المستأجر من العين بسبب التأخير فى سداد الأجرة إعمالا للشرط الفاسخ الصريح إذا سدد المستأجر الأجرة والمصاريف والأتعاب عند تنفيذ الحكم .
(ب) إذا أجر المستأجر المكان المؤجر من الباطن أو تنازل عنه أو تركه للغير بأى وجه من الوجوه بغير إذن كتابى صريح من المالك للمستأجر الأصلى وذلك مع عدم الإخلال بأحكام المواد التى تجيز للمستأجر ذلك .
(ج) إذا استعمل المستأجر المكان المؤجر أو سمح باستعماله بطريقة تخالف شروط الإيجار المعقولة والمتعارف عليها وتضر بمصلحة المؤجر أو استعمله فى غير الأغراض المؤجر من أجلها ، وذلك بعد إعذاره بإعادة الحالة إلى ما كانت عليه .
(د) إذا استعمل المستأجر المكان المؤجر أو سمح باستعماله بطريقة ضارة بالصحة أو مقلقة للراحة أو منافية للآداب العامة متى ثبت ذلك بحكم قضائى نهائى .$m247$,'86411701c8bb4520dec013affd2d05f1'),
(32,0,$m247$المادة 32$m247$,$m247$يجوز للمالك زيادة عدد الوحدات السكنية فى المبنى المؤجر بالإضافة أو التعلية ولو كان عقد الإيجار يمنع ذلك ولا يخل هذا بحق المستأجر فى إنقاص الأجرة إن كان لذلك محل .
ويجوز بحكم من قاضى الأمور المستعجلة الترخيص بإخلاء وهدم ما قد يعترض الإضافة أو التعلية من أجزاء الأماكن غير السكنية ، بشرط تعويض ذوى الشأن وإعطائهم حق العودة ، وفقا لأحكام الفصل الأول من الباب الثانى من هذا القانون .
أما إذا كان الجزء من المكان مخصصا للسكنى فلا يجوز الحكم بإخلائه وهدمه إلا إذا قام المالك بتدبير مسكن آخر مناسب وذلك دون الإخلال بحق المستأجر فى العودة إلى المبنى الجديد ، وفقا لأحكام الفصل الأول من الباب الثانى من هذا القانون .$m247$,'511d5d701390656cce2ccbc42269fe82'),
(33,0,$m247$المادة 33$m247$,$m247$تكون قيمة استهلاك المياه على عاتق شاغلى الأماكن القائمة وقت العمل بهذا القانون أيا كان تاريخ إنشائها أو التى تقام بعد العمل به وفقا للقواعد الآتية :
(أ) قيمة ما تسجله العدادات الفرعية المركبة بوحداتهم إن وجدت عدادات بجميع وحدات المبنى ، وفى حالة عدم تساوى قراءة العداد الرئيسى مع مجموع قراءات العدادات الفرعية يوزع الفرق بالتساوى بين وحدات المبنى .
(ب) إذا لم توجد عدادات فرعية بأية وحدة من وحدات المبنى فتوزع قيمة استهلاك المياه التى يسجلها العداد الرئيسى على الشاغلين بحسب حجرات كل وحدة إلى عدد حجرات المبنى جميعه وتحسب الصالة حجرة واحدة ولو تعددت .
(ج) إذا وجدت عدادات فرعية ببعض وحدات المبنى دون البعض الآخر فتوزع قيمة استهلاك المياه التى يسجلها العداد الرئيسى بعد استنزال ما تسجله العدادات الفرعية على الشاغلين على الوجه المبين بالفقرة السابقة .
(د) فى الحالات التى يتم فيها توريد المياه عن غير طريق الجهة القائمة على ذلك يتحمل الشاغلون بقيمة استهلاك المياه وفقا لما يتم الاتفاق عليه بينهم وبين المؤجرين بما لا يجاوز 7% (سبعة فى المائة) من القيمة الإيجارية المحددة قانونا .
ويقع باطلا كل اتفاق يخالف القواعد سالفة الذكر .$m247$,'3596bb70c301bb60a761eeec2e7d0e9e'),
(34,0,$m247$المادة 34$m247$,$m247$تخفض الأجرة الشهرية بمقدار (5%) خمسة فى المائة بحد أدنى مقداره مائتا مليم بالنسبة إلى شاغلى الأماكن الذين لم يكونوا ملتزمين بقيمة استهلاك المياه فى 18/8/1969 ، كما يسرى هذا الخفض إذا كان قد جرى العمل بين المؤجر والمستأجر على تحمل المؤجر بقيمة الاستهلاك على الرغم من النص فى عقد الإيجار على التزام المستأجر بها ، على ألا يسرى هذا الخفض بالنسبة إلى الأماكن التى أنشئت قبل أول يناير سنة 1944
ويجوز لكل من المالك أو المستأجر تركيب عداد خاص على نفقته لحساب استهلاك المياه بالوحدة المؤجرة ، وذلك دون اشتراط موافقة الآخر ، وفى هذه الحالة تتم المحاسبة وفقا للأوضاع المبينة فى المادة السابقة .$m247$,'f3110c76affcf675fc6140a852fa79ab'),
(35,0,$m247$المادة 35$m247$,$m247$يلتزم ملاك المبانى التى تنشأ بعد تاريخ العمل بهذا القانون بتوفير التوصيلات اللازمة لتركيب عداد خاص بكل وحدة من وحدات المبنى بمعرفة المستأجر وعلى نفقته ويراعى بقدر الإمكان وضعه فى مكان تسهل معه قراءة العداد دون الحاجة إلى دخول الوحدة ذاتها .$m247$,'f2ba48ed382173aa7d1c1e5963e83bca'),
(36,0,$m247$المادة 36$m247$,$m247$يصدر قرار من المحافظ المختص بتحديد وكيفية توزيع قيمة استهلاك المياه فى الحالات التى توجد فيها غرف خدمات ومنافع مشتركة أو حدائق أو مأوى أو جراجات أو محال عامة أو أماكن تمارس فيها صناعة أو تجارة أو ما شابه ذلك من أنشطة غير سكنية .$m247$,'c69ddad5f127db6dd48b16d568f0386d'),
(37,0,$m247$المادة 37$m247$,$m247$فى جميع الحالات يلتزم المستأجر بأن يسدد قيمة استهلاك المياه إلى المؤجر فى المواعيد المحددة لسداد الأجرة ، أو كلما طلب المؤجر ذلك ، ما لم تضع الجهات الموردة للمياه أنظمة وقواعد لاقتضاء هذه القيمة من شاغلى المبانى مباشرة . وعلى المؤجر إثبات تقاضيه تلك القيمة بإيصال مستقل أو مع إيصال استلام الأجرة .
ويترتب على التأخير فى سداد قيمة استهلاك المياه المستحقة للمؤجر ما يترتب على التأخير فى سداد الأجرة من آثار .
وإذا ترتب على تأخر المؤجر فى أداء قيمة استهلاك المياه إلى الجهة الموردة لها قطعها عن المكان المؤجر أو الشروع فى ذلك كان للمستأجر أن يؤدى قيمة الاستهلاك إلى الجهة المذكورة مباشرة خصما مما يستحق للمؤجر لديه ، وذلك دون حاجة إلى أية إجراءات .$m247$,'c866a963c7638cc4669c114d425a85db'),
(38,0,$m247$المادة 38$m247$,$m247$يلتزم ملاك المبانى المؤجرة كلها أو بعضها بأن يقوموا بعمل الخزانات وتركيب الطلمبات اللازمة لتوفير المياه لجميع أدوار المبنى ، وأن يستخدموا مواسير مياه ذات أقطار كافية تسمح بمرور القدر المناسب للاستهلاك ، وذلك فى المناطق ووفقا للقواعد والشروط التى يصدر بها قرار من المحافظ بعد أخذ رأى الجهات القائمة على مرفق المياه وإذا امتنع المالك من التنفيذ تطبق أحكام الفقرتين الثانية والثالثة من المادة (60) من هذا القانون دون حاجة إلى العرض على اللجنة أو المحكمة .
وتطبق أحكام المادة (61) بالنسبة إلى المبالغ التى ينفقها الملاك فى سبيل تنفيذ الالتزام المنصوص عليه بالفقرة السابقة .
ويحظر على شاغل العين تركيب طلمبة أو أى جهاز من شأنه ضخ المياه إلى الوحدة الخاصة به بالمخالفة للقواعد والشروط المقررة بمعرفة الجهة القائمة على مرفق المياه ، وفى حالة المخالفة تتم إزالة أسباب المخالفة إداريا وعلى نفقة المخالف فضلا عن العقوبة المقررة .$m247$,'176ed9ee67a8acedef2f4c7cde6330e3'),
(39,0,$m247$المادة 39$m247$,$m247$لا يجوز للمالك فى غير المصايف والمشاتى المحددة وفقا لأحكام هذا القانون أن يؤجر سوى وحدة واحدة مفروشة فى العقار الذى يملكه وفى تطبيق هذه المادة يعتبر الشخص وزوجه وأولاده القصر مالكا واحدا .
واستثناء من ذلك يجوز للمالك أن يؤجر وحدة أخرى مفروشة فى أى من الأحوال أو الأغراض الآتية :
(أ) التأجير لإحدى الهيئات الأجنبية أو الدبلوماسية أو القنصلية أو المنظمات الدولية أو الإقليمية أو لأحد العاملين بها من الأجانب ، أو للأجانب المرخص لهم بالعمل أو الإقامة بجمهورية مصر العربية .
(ب) التأجير للسائحين الأجانب أو لإحدى الجهات المرخص لها فى مباشرة أعمال السياحة بغرض إسكان السائحين وذلك فى المناطق التى يصدر بتحديدها قرار من وزير السياحة بالاتفاق مع المحافظ المختص .
على أنه إذا اتخذت الملكية شكل وحدات مفرزة فى عقارات ، فإنه لا يكون للمالك فى هذه الحالة سوى تأجير وحدتين مفروشتين فى كل مدينة مهما تعددت الوحدات المملوكة له ، وذلك بنفس الشروط والأوضاع المبينة بهذه المادة .
كما يكون للمالك إذا أقام خارج الجمهورية بصفة مؤقتة أن يؤجر سكنه مفروشا أو خاليا وعليه فى هذه الحالة أن يخطر المستأجر لإخلاء العين فى الموعد المحدد لعودته للإقامة بالجمهورية وبشرط أن يمنح المستأجر أجلا مدته ثلاثة أشهر من تاريخ إخطاره ليقوم بإخلاء العين وردها إلى مالكها ، وإلا اعتبر شاغلا للعين دون سند قانونى وذلك أيا كانت مدة الإيجار المتفق عليها .$m247$,'2f76821a91aff991d9147d3eaf5bb99c'),
(40,0,$m247$المادة 40$m247$,$m247$لا يجوز للمستأجر فى غير المصايف والمشاتى المحددة وفقا لأحكام هذا القانون أن يؤجر المكان المؤجر له مفروشا أو خاليا إلا فى الحالات الآتية :
(أ) إذا أقام خارج الجمهورية بصفة مؤقتة :
وعلى المستأجر الأصلى فى هذه الحالة أن يخطر المستأجر من الباطن لإخلاء العين فى الموعد المحدد لعودته للإقامة بالجمهورية ، بشرط أن يمنح المستأجر من الباطن أجلا مدته ثلاثة أشهر من تاريخ إخطاره ليقوم بإخلاء العين وردها إلى المستأجر الأصلى وإلا اعتبر شاغلا للعين دون سند قانونى ، وذلك أيا كانت مدة الإيجار المتفق عليه .
(ب) إذا كان مزاولا لمهنة حرة أو حرفة غير مقلقة للراحة أو مضرة بالصحة وأجر جزءا من المكان المؤجر له لهذا الغرض إلى من يمارس مهنة أو حرفة ولو كانت مغايرة لمهنته أو حرفته .
(ج) إذا أجر المكان المؤجر له كله أو جزءا منه للطلاب الذين يدرسون فى غير المدن التى تقيم فيها أسرهم .
(د) التأجير للعمال فى مناطق تجمعاتهم ، وكذا التأجير للعاملين بمختلف أجهزة الدولة والحكم المحلى والقطاع العام وذلك فى المدن التى يعينون بها أو ينقلون إليها .
(هـ) فى الحالات والشروط المبينة بالبندين (أ ، ب) من المادة السابقة .
وفى جميع الأحوال يشترط ألا يزيد مجموع ما يقوم المستأجر هو وزوجته وأولاده القصر بتأجيره مفروشا على شقة واحدة فى نفس المدينة .
ولا يقيد من حكم هذه المادة سوى مستأجرى وحدات الأماكن الخالية .$m247$,'f3c34fa5c9d96bea76bee5861d03f5c7'),
(41,0,$m247$المادة 41$m247$,$m247$فيما عدا الفنادق والنزل يجب على كل من أجر مكانا مفروشا أو جزءا منه أو آوى أو أسكن أى أجنبى أو مصرى ، أن يخطر قسم الشرطة الذى يتبعه المكان باسم الشاغل للمكان وجنسيته ورقم جواز سفره إن كان أجنبيا ورقم ومكان وتاريخ صدور بطاقته الشخصية أو العائلية إن كان مصريا ، ومدة الإيجار أو الإشغال والغرض منه وتاريخ بداية هذه المدة ونهايتها ، وذلك خلال ثلاثة أيام من تاريخ تأجير أو شغل المكان أيهما أسبق .$m247$,'c2c9362d4e58a22dfe4b5ff2dbf043a7'),
(42,0,$m247$المادة 42$m247$,$m247$على المؤجر أن يطلب قيد عقود الإيجار المفروش التى تبرم تطبيقا لأحكام المادتين 39 ، 40 لدى الوحدة المحلية المختصة وتلزم هذه الجهة بإخطار مصلحة الضرائب شهريا بما تجمع لديها من بيانات فى هذا الشأن .$m247$,'bb5a8b09fbab6a68b6e60e4b14c3ade2'),
(43,0,$m247$المادة 43$m247$,$m247$لا تسمع دعاوى المؤجر كما لا تقبل الطلبات المقدمة منه الناشئة أو المترتبة على تطبيق أحكام المادتين 39 ، 40 إلا إذا كانت العقود المبرمة وفقا لها مقيدة على الوجه المنصوص عليه فى المادة السابقة .
ولا يجوز للمؤجر الاستناد إلى العقود غير المقيدة لدى أية جهة من الجهات .$m247$,'668b27854f0c99f6ac84907f8fda890b'),
(44,0,$m247$المادة 44$m247$,$m247$مع عدم الإخلال بأحكام المادتين 39 ، 40 يجوز للملاك ولمستأجرى الأماكن الخالية فى المصايف والمشاتى التى يصدر بتحديدها قرار من وزير الإسكان والتعمير بعد أخذ رأى المحافظ المختص ، تأجير الأماكن مفروشة طبقا للشروط والأوضاع التى ينص عليها هذا القرار .$m247$,'bc59532d0d384e8d70a301475b38130a'),
(45,0,$m247$المادة 45$m247$,$m247$فى جميع الأحوال التى يجوز فيها للمستأجر تأجير المكان أو جزء من المكان المؤجر مفروشا يستحق المالك أجرة إضافية عن مدة التأجير مفروشا بواقع نسبة من الأجرة القانونية تحسب على الوجه الآتى :
(أ) أربعمائة فى المائة (400%) عن الأماكن المنشأة قبل أول يناير سنة 1944
(ب) مائتان فى المائة (200%) عن الأماكن المنشأة منذ أول يناير سنة 1944 وقبل 5 نوفمبر سنة 1961
(ج) مائة وخمسون فى المائة (150%) عن الأماكن المنشأة منذ 5 نوفمبر سنة 1961 حتى تاريخ العمل بهذا القانون .
(د) مائة فى المائة (100%) عن الأماكن التى يرخص فى إقامتها اعتبارا من تاريخ العمل بأحكام هذا القانون .
وفى حالة تأجير المكان المفروش جزئيا يستحق المالك نصف النسب الموضحة فى هذه المادة .$m247$,'38beb2b1426d187d2434516aaf23421e'),
(46,0,$m247$المادة 46$m247$,$m247$يحق للمستأجر الذى يسكن فى عين استأجرها مفروشة من مالكها لمدة خمس سنوات متصلة سابقة على تاريخ العمل بهذا القانون البقاء فى العين ولو انتهت المدة المتفق عليها وذلك بالشروط المنصوص عليها فى العقد ، ولا يجوز للمؤجر طلب إخلائه إلا إذا كان أجرها بسبب إقامته فى الخارج وثبتت عودته نهائيا أو إذا أخل المستأجر بأحد التزاماته وفقا لأحكام البنود (أ ، ب ، ج ، د) من المادة 31 من هذا القانون .
فإذا كانت العين قد أجرت مفروشة من مستأجرها الأصلى فإنه يشترط لاستفادة المستأجر من الباطن من حكم الفقرة السابقة أن يكون قد أمضى فى العين مدة عشر سنوات متصلة سابقة على تاريخ العمل بهذا القانون .$m247$,'2074850bb2c3e023c3e1e3dffa11564f'),
(47,0,$m247$المادة 47$m247$,$m247$فى غير الحالات المنصوص عليها فى المادة السابقة ، يجب على الملاك والمستأجرين المؤجرين لأماكن مفروشة حتى تاريخ العمل بهذا القانون تعديل الأوضاع وفقا لأحكام هذا الفصل خلال ستة أشهر من ذلك التاريخ أو انتهاء مدد العقود أيهما أقرب ويسلم المكان إلى المالك أو المستأجر الأصلى بحسب الأحوال ، ويجوز لمجلس الوزراء لاعتبارات المصلحة العامة التى يراها أن يمد هذه المهلة لمدة أو لمدد لا تجاوز سنتين من تاريخ العمل بهذا القانون .$m247$,'c99296204531877da8e8e373dfe30903'),
(48,0,$m247$المادة 48$m247$,$m247$لا يفيد من أحكام هذا الفصل سوى الملاك والمستأجرين المصريين .
على ألا تسرى أحكام الفصلين الثانى والرابع من الباب الأول وكذا أحكام الفصل الأول من الباب الرابع من هذا القانون على مشروعات الإسكان والامتداد العمرانى التى تقام وفقا لأحكام القانون المنظم لاستثمار المال العربى والأجنبى والمناطق الحرة$m247$,'e1b35031aa72ffb1c48d296ab4458bc7'),
(49,0,$m247$المادة 49$m247$,$m247$يجوز لمالك المبنى المؤجرة كل وحداته لغير أغراض السكن ، أن ينبه على المستأجرين بإعلان على يد محضر بإخلاء المبنى بقصد إعادة بنائه وزيادة مسطحاته وعدد وحداته وذلك وفقا للشروط والأوضاع الآتية :
(أ) أن يحصل المالك على التصاريح والتراخيص والمواصفات اللازمة للهدم وإعادة البناء وفقا لأحكام القانون على أن يتضمن الترخيص بناء وحدات جديدة تصلح لذات الغرض الذى كانت تستعمل فيه الوحدات المرخص بهدمها .
(ب) ألا تقل جملة مسطحات أدوار المبنى الجديد عن أربعة أمثال مسطحات أدوار المبنى قبل الهدم .
(ج) أن يشتمل المبنى الجديد على وحدات سكنية أو فندقية لا يقل مجموع مسطحاتها عن خمسين فى المائة (50%) من مجموع مسطحاته .
(د) أن يقوم المالك بتوفير وحدة مناسبة بأجر مماثل ليمارس المستأجر نشاطه فيها وإلا التزم بتعويضه بمبلغ مساو للفرق بين القيمة الإيجارية للوحدة التى يشغلها والقيمة الإيجارية للوحدة التى يتعاقد على ممارسة نشاطه فيها لمدة خمس سنوات أو للمدة التى تنقضى إلى أن يعود إلى المكان ببنائه بذات القيمة الإيجارية الأولى ، أو يدفع مبلغا مساويا للقيمة الإيجارية للوحدة التى يشغلها خالية عن مدة عشر سنوات بحد أدنى قدره ألفا جنيه أيهما أكبر .
(هـ) أن يحدد المالك موعدا يتم فيه الإخلاء على ألا يكون هذا الموعد قبل انقضاء أطول مدة إيجار متفق عليها عن أى وحدة من وحدات المبنى وبشرط ألا يقل عن ستة أشهر من تاريخ التنبيه بالإخلاء .$m247$,'c8d7182e6c23bd7fdebd1c1bea42b81f'),
(50,0,$m247$المادة 50$m247$,$m247$لا يلتزم المستأجرون بالإخلاء إلا بموافقتهم جميعا عليه وذلك بموجب خطابات للمالك موصى عليها مصحوبة بعلم الوصول أو بإقرارات كتابية منهم .
فإذا انقضت ثلاثة أشهر على التنبيه بالإخلاء دون موافقة جميع المستأجرين عليه جاز للمالك أن يلجأ إلى المحكمة المختصة للحصول على حكم بالإخلاء ، ويكون هذا الحكم قابلا للتنفيذ بعد انقضاء ثلاثة أشهر من تاريخ النطق به ، ويشترط أداء التعويض المنصوص عليه فى المادة السابقة أو إيداعه المحكمة المختصة إيداعا غير مشروط لصالح المستأجرين .
وإذا امتنع أى من المستأجرين عن تنفيذ الإخلاء فى الموعد المحدد بالتنبيه المعلن إليهم من المالك بعد موافقة جميع المستأجرين أو بناء على حكم المحكمة المختصة وقيام المالك بأداء التعويض المستحق ، جاز للمالك أن يستصدر من قاضى الأمور المستعجلة حكما بطرد الممتنع عن الإخلاء فورا .$m247$,'a8bbca3c25537183def5b7468f2d2cb0'),
(51,0,$m247$المادة 51$m247$,$m247$لا تسرى أحكام هذا الفصل على المبانى المؤجرة لاستعمالها دورا للتعليم حكومية أو خاصة تخضع للإشراف الحكومى وكذلك المستشفيات العامة أو الخاصة الخاضعة لإشراف وزارة الصحة ومحطات تموين وخدمة السيارات أو المنشآت السياحية أو الفندقية أو المصرفية وغيرها من المنشآت ذات الأهمية للاقتصاد أو الأمن القومى أو التى تقدم خدمات عامة للجمهور والتى يصدر بتحديدها قرار من وزير الإسكان والتعمير بعد موافقة الوزير المختص .
أما غير ذلك من المبانى المؤجرة للجهات الحكومية أو لوحدات الحكم المحلى أو للهيئات العامة أو لوحدات القطاع العام فتسرى عليها أحكام هذا الفصل على أن تزاد المهلة بالنسبة إليها إلى ثلاث سنوات من تاريخ التنبيه بالإخلاء إذا طلبت الجهة المستأجرة الإفادة من هذه المهلة وذلك مقابل التنازل عن تعويض الإخلاء .$m247$,'0a504a0743119c416b6ea3833a2e9952'),
(52,0,$m247$المادة 52$m247$,$m247$على المالك أو خلفه العام أو الخاص أن يتم الهدم فى مدة أقصاها ثلاثة أشهر من تاريخ إخلاء المبنى كله ، وأن يشرع فى إعادة البناء خلال ثلاثة أشهر من تاريخ انتهاء الهدم .
فإذا لم يتم الهدم خلال المدة المشار إليها دون عذر مقبول كان لمن يرغب من المستأجرين بحكم من قاضى الأمور المستعجلة الحق فى العودة إلى شغل وحدته متى كان ذلك ممكنا ، وإلا كان له الحق فى تعويض قانونى مماثل للتعويض المنصوص عليه فى المادة (49) بالإضافة إلى حقه فى الاحتفاظ بالتعويض الذى تقاضاه من المالك عند موافقته على الإخلاء ، وذلك كله دون إخلال بحقه فى المطالبة قضاء بما يزيد على هذا التعويض إن كان له مقتض .$m247$,'2af7a5259760b80d2f7aafcede2a6b41'),
(53,0,$m247$المادة 53$m247$,$m247$إذا تم الهدم ولم يشرع المالك أو خلفه فى البناء خلال المدة المشار إليها فى المادة السابقة ، أو شرع فى البناء ثم تعمد عدم إتمامه فى الوقت الذى تحدده الجهة المختصة بشئون التنظيم جاز للمحافظ المختص أن يعهد إلى إحدى الجهات القيام بالبناء أو تكملته على حساب المالك وفقا للقواعد التى يصدر بها قرار من وزير الإسكان والتعمير ويكون للمبالغ المستحقة لهذه الجهة حق امتياز على المبنى الذى قامت بإنشائه أو استكماله من ذات مرتبة الامتياز المقرر للمبالغ المستحقة للمقاولين والمهندسين المعماريين طبقا لنص المادة (1148) من القانون المدنى .
ويكون للجهة المشار إليها تأجير المبنى واقتضاء أجرته إلى أن تستوفى المبالغ التى أنفقتها والمصروفات الإدارية ، ويحق للمالك أن يحصل على 20% من تلك الأجرة شهريا .$m247$,'fe42477289d8716f6626fbbdf3a4f77d'),
(54,0,$m247$المادة 54$m247$,$m247$لمستأجرى الوحدات التى يتم هدمها وفقا لأحكام هذا الفصل الحق فى شغل الوحدات بالعقار الجديد الذى أعيد بناؤه ويلتزم المالك أو خلفه العام أو الخاص بإنشاء وحدات جديدة تصلح لذات الغرض الذى كانت تستعمل فيه الوحدات المهدومة ما لم تحل التشريعات السارية دون ذلك . وفى هذه الحالة يستحق المستأجر تعويضا آخر مساو للتعويض المنصوص عليه فى المادة 49 من هذا القانون .
ويلتزم المالك بإخطار مستأجرى وحدات العقار المهدوم بإتمام إعادة البناء بإنذار على يد محضر ، يرسل إليهم على محال إقامتهم التى يخطرون بها المالك عند الإخلاء ، وذلك خلال مدة لا تجاوز شهرا من تاريخ إتمام البناء .
وعلى المستأجر إبداء رغبته بكتاب موصى عليه مصحوب بعلم الوصول فى شغل وحدة فى العقار المنشأ فى مدة لا تجاوز شهرين من تاريخ إخطاره وإلا سقط حقه فى ذلك .
وتحدد بقرار من وزير الإسكان والتعمير قواعد وإجراءات وأولويات شغل مستأجرى العقار المهدوم لوحدات المبنى الجديد .$m247$,'85482fb1638b6d12e6cba8ca54836ecd'),
(55,0,$m247$المادة 55$m247$,$m247$تسرى أحكام هذا الفصل على المبانى والمنشآت التى يخشى من سقوطها أو سقوط جزء منها مما يعرض الأرواح والأموال للخطر ، كما تسرى على المنشآت المشار إليها إذا كانت تحتاج إلى ترميم أو صيانة لتأمين سلامتها أو للحفاظ عليها فى حالة جيدة .
وتبين القرارات التى يصدرها وزير الإسكان والتعمير الأعمال التى تعتبر من أعمال الترميم والصيانة وحدودها فى تطبيق أحكام هذا الفصل .$m247$,'c9a907eaf47966aff6356d6a926f0525'),
(56,0,$m247$المادة 56$m247$,$m247$تتولى الجهة الإدارية المختصة بشئون التنظيم معاينة وفحص المبانى والمنشآت وتقرر ما يلزم اتخاذه للمحافظة على الأرواح والأموال سواء بالهدم الكلى أو الجزئى أو التدعيم أو الترميم أو الصيانة لجعلها صالحة للغرض المخصصة من أجله .
ويتضمن القرار تحديد المدة اللازمة لتنفيذ الأعمال المطلوبة وما إذا كانت تستوجب إخلاء المبنى مؤقتا كليا أو جزئيا .$m247$,'05d6bbd2568d56aaf6b4f1df14cd2f85'),
(57,0,$m247$المادة 57$m247$,$m247$تشكل فى كل وحدة من وحدات الحكم المحلى ، لجنة أو أكثر يصدر بها قرار من المحافظ المختص ، تضم اثنين من المهندسين المعماريين أو المدنيين المقيدين بنقابة المهندسين ، تتولى دراسة التقارير المقدمة من الجهة الإدارية المختصة بشئون التنظيم فى شأن المبانى المشار إليها فى المادة (55) وإجراء المعاينات على الطبيعة ، وإصدار قرارات فى شأنها على وجه السرعة .
ويبين القرار الذى يصدره وزير الإسكان والتعمير كيفية تشكيل تلك اللجان والقواعد والإجراءات التى تتبع فى مزاولة أعمالها .$m247$,'8b3093b01b1f346f1fea5a3e73fd5158'),
(58,0,$m247$المادة 58$m247$,$m247$يعلن قرار اللجنة بالطريق الإدارى إلى ذوى الشأن من الملاك وشاغلى العقار وأصحاب الحقوق وتعاد صورة منه إلى الجهة الإدارية المختصة بشئون التنظيم ، فإذا لم يتيسر إعلانهم بسبب غيبتهم غيبة منقطعة أو لعدم الاستدلال على محال إقامتهم أو لامتناعهم عن تسلم الإعلان تلصق نسخة من القرار فى مكان ظاهر بواجهة العقار وفى لوحة الإعلانات فى مقر نقطة الشرطة الواقع فى دائرتها العقار وفى مقر عمدة الناحية ولوحة الإعلانات فى مقر المجلس المحلى المختص بحسب الأحوال .
وتتبع الطريقة ذاتها فى إعلان القرارات الخاصة بالمنشآت التى لم يستدل على ذوى الشأن فيها .$m247$,'4d4acd365ef17201aa91dc62ab11c42c'),
(59,0,$m247$المادة 59$m247$,$m247$لكل من ذوى الشأن أن يطعن فى القرار المشار إليه بالمادة السابقة فى موعد لا يجاوز خمسة عشر يوما من تاريخ إعلانه بالقرار ، أمام المحكمة المنصوص عليها فى المادة (18) من هذا القانون .
وعلى قلم كتاب المحكمة إعلان الجهة الإدارية القائمة على شئون التنظيم وذوى الشأن من ملاك العقارات وأصحاب الحقوق بالطعن فى قرار اللجنة وبالجلسة المحددة لنظر هذا الطعن .
وتفصل المحكمة على وجه السرعة إما برفض الطعن أو بقبوله وإعادة النظر فى القرار المطعون عليه ، وعليها فى حالة الحكم بالهدم الكلى أو الجزئى أو التدعيم أو الترميم أو الصيانة أن تحدد أجلا لتنفيذ حكمها .$m247$,'1629efc3502fcdf1177b3cf6ad09af89'),
(60,0,$m247$المادة 60$m247$,$m247$مع عدم الإخلال بالأحكام الخاصة بتوجيه وتنظيم أعمال البناء ، يجب على ذوى الشأن أن يبادروا إلى تنفيذ قرار اللجنة النهائى أو حكم المحكمة الصادر فى شأن المنشآت الآيلة للسقوط والترميم والصيانة وفقا لأحكام هذا القانون ، وذلك فى المدة المحددة لتنفيذه .
وللجهة الإدارية المختصة بشئون التنظيم فى حالة امتناع ذوى الشأن عن تنفيذ قرار اللجنة النهائى أو حكم المحكمة بحسب الأحوال فى المدة المحددة لذلك ، أن تقوم بتنفيذه على نفقة صاحب الشأن وتحصل قيمة التكاليف وجميع النفقات بطريق الحجز الإدارى .
ويجوز للمستأجر إذا تأخر كل من ذوى الشأن والجهة الإدارية المذكورة عن القيام بتنفيذ ما نص عليه القرار النهائى أو قضى به حكم المحكمة بحسب الأحوال ، أن يحصل على إذن من القضاء المستعجل فى أن يجرى الأعمال المقررة دون حاجة إلى الحصول على موافقة المالك ، وأن يستوفى ما أنفقه خصما من مستحقات المالك لديه .$m247$,'afc0f718764faf33799b10eeb9f6bbfd'),
(61,0,$m247$المادة 61$m247$,$m247$على كل من المالك والمستأجر فور إتمام أعمال الترميم أو الصيانة إخطار الجهة الإدارية المختصة بشئون التنظيم على أن يتضمن إخطاره طلب اعتماد المبالغ التى أنفقت وذلك وفقا لما تحدده اللائحة التنفيذية .
وعلى الجهة الإدارية المذكورة أن تبت فى الطلب وتخطر كلا من الملاك والمستأجرين بقرارها فى هذا الشأن خلال ثلاثة أسابيع .
وبمجرد إبلاغ الجهة الإدارية القرار المذكور إلى المالك يكون من حقه تقاضى الأجرة اعتبارا من أول الشهر التالى لإتمام الأعمال المشار إليها على أساس زيادة الأجرة السنوية بمقدار 20% (عشرون فى المائة) من قيمة أعمال الترميم والصيانة ، وتتبع أحكام زيادة الأجرة المنصوص عليها فى هذه الفقرة فى الحالات التى يتم فيها إجراء الترميم أو الصيانة بناء على اتفاق صريح كتابى بين المالك والمستأجر .
ويترتب على عدم سداد هذه الزيادة ما يترتب على عدم سداد الأجرة من آثار .$m247$,'f04b7468acf37584fd45a9b7dd6fedfc'),
(62,0,$m247$المادة 62$m247$,$m247$يجوز لوزارة الإسكان والتعمير والأجهزة التابعة لها ووحدات الحكم المحلى والمصارف أن تقرض بشروط ميسرة ملاك المبانى أو شاغليها الخاضعة لأحكام هذا القانون للقيام بترميمها وصيانتها .
ويصدر بشروط وقواعد الإقراض قرار من وزير الإسكان والتعمير بعد الاتفاق مع وزير المالية .
وتعفى القروض من جميع الضرائب والرسوم وتحصل بطريق الحجز الإدارى .
ويكون للقروض امتياز على العين التى تم ترميمها أو صيانتها يجىء فى الترتيب مع الامتياز المقرر فى القانون المدنى للمقاولين والمهندسين .$m247$,'88c59f12cf120ebe6c812d9804919a18'),
(63,0,$m247$المادة 63$m247$,$m247$إذا اقتضت أعمال الترميم أو الصيانة إخلاء المبنى مؤقتا من شاغليه حرر محضر إدارى بأسماء المستأجرين للقاطنين دون سواهم ، وتقوم الجهة الإدارية المختصة بشئون التنظيم بإخطارهم بالإخلاء فى المدة التى تحددها وإذا لم يتم الإخلاء بعد انقضائها جاز تنفيذه بالطريق الإدارى ولشاغلى العين الحق فى العودة إلى العين بعد ترميمها دون حاجة إلى موافقة المالك ، ويتم ذلك بالطريق الإدارى فى حالة امتناع المالك .
وتضاف الأجرة خلال فترة الإخلاء إلى تكاليف الإصلاح اللازمة لتنفيذ أعمال الترميم والصيانة التى تحددها الجهة الإدارية المختصة .
ولا يجوز مد هذه المدة إلا بقرار من الجهة المذكورة ، وفى هذه الحالة يجوز لشاغل العين التظلم من القرار أمام رئيس المحكمة المنصوص عليها فى المادة 18 من هذا القانون .
وتعتبر العين خلال هذه المدة فى حيازة المستأجر قانونا ولا يجوز للمالك أن يغير فى معالم العين كل ذلك ما لم يبد المستأجر رغبته فى إنهاء العقد خلال خمسة عشر يوما من تاريخ إخطاره بقرار الإخلاء المؤقت .$m247$,'b8d7f0732da00393ae0da09f622713ca'),
(64,0,$m247$المادة 64$m247$,$m247$على شاغلى العين الصادر قرار أو حكم نهائى بهدمها أن يبادروا إلى إخلائها فى المدة المحددة فى الحكم أو القرار فإذا امتنعوا عن الإخلاء كان للجهة الإدارية المختصة بشئون التنظيم إخلاؤهم بالطريق الإدارى وعلى نفقتهم دون أية إجراءات .$m247$,'ccfd0d8af45dcde0c18d51e7a2283c24'),
(65,0,$m247$المادة 65$m247$,$m247$يجوز للجهة الإدارية المختصة بشئون التنظيم فى أحوال الخطر الداهم إخلاء البناء وكذلك المبانى المجاورة عند الضرورة من السكان بالطريق الإدارى واتخاذ ما تراه لازما من الاحتياطات والتدابير فى مدة لا تقل عن أسبوع إلا فى حالة تهديد البناء بالانهيار العاجل فيكون لها فى هذه الحالة الحق فى إخلائه فورا .
كما يكون لها فى حالة الضرورة القصوى هدم البناء بموجب حكم من قاضى الأمور المستعجلة بالمحكمة الكائن فى دائرتها العقار .$m247$,'fac79af5b9fe99e1a089dbc924e2bde7'),
(66,0,$m247$المادة 66$m247$,$m247$مع عدم الإخلال بأحكام القانون رقم 169 لسنة 1961 بتقرير بعض الإعفاءات الضريبية على العقارات المبنية وخفض الإيجارات بمقدار الإعفاء والقانون رقم 38 لسنة 1967 فى شأن النظافة العامة ، والقانون رقم 46 لسنة 1968 باستثناء بعض الأماكن من الإعفاءات الضريبية المقررة بالقانون رقم 169 لسنة 1961 المشار إليه ، يعفى شاغلو المساكن من أداء الضرائب العقارية الأصلية والإضافية إذا زاد متوسط الإيجار الشهرى للغرفة الواحدة فيها على ثلاثة جنيهات ولم يجاوز خمسة جنيهات .
كما يعفى شاغلو المساكن من أداء الضريبة الأصلية دون الضرائب الإضافية وذلك إذا زاد متوسط الإيجار الشهرى للغرفة الواحدة فيها على خمسة جنيهات ولم يجاوز ثمانية جنيهات .
كما يعفى أصحاب العقارات التى أنشئت قبل أول يناير سنة 1944 من ضرائب الدفاع والأمن القومى .$m247$,'d9e96787b344ca375358dfc2a52094ac'),
(67,0,$m247$المادة 67$m247$,$m247$تسرى الإعفاءات المقررة بالمادة السابقة اعتبارا من أول يناير سنة 1977 على المساكن المنشأة أو المشغولة لأول مرة بعد 18/8/1969 ، وعلى لجان تقدير الإيجارات والمحكمة المختصة مراعاة ذلك عند تقدير الأجرة وفقا لأحكام هذا القانون .
على أنه بالنسبة إلى المساكن المنشأة أو المشغولة لأول مرة منذ تاريخ العمل بهذا القانون يعفى شاغلو المساكن من أداء الضرائب العقارية الأصلية والإضافية إذا لم يجاوز متوسط الإيجار الشهرى للغرفة الواحدة فيها ثمانية جنيهات ، أما إذا زاد المتوسط عن ذلك ولم يجاوز عشرة جنيهات شهريا فيعفى شاغلو المساكن من أداء الضرائب الأصلية دون الضرائب الإضافية .$m247$,'8c15163ecf515d937357ef185ec23f21'),
(68,0,$m247$المادة 68$m247$,$m247$يجوز لأجهزة الدولة ووحدات الحكم المحلى وشركات القطاع العام والجمعيات التعاونية لبناء المساكن وصناديق التأمين الخاصة والشركات الخاصة والأفراد إنشاء المبانى بقصد تمليك كل أو بعض وحداتها السكنية .
ويحظر على الجهات القائمة على منح موافقات وتراخيص البناء ، التصريح للشركات الخاصة والأفراد بإقامة مبان أو أجزاء منها بقصد التمليك إلا فى حدود عشرة فى المائة (10%) من جملة الاستثمارات المقررة لكل مستوى من مستويات الإسكان المختلفة ، ويصدر قرار من وزير الإسكان والتعمير بقواعد الأولوية فى حدود هذه النسبة .
ويلتزم كل من البائع والمشترى فى حالة التعاقد بأن يكتتب بـ 5% من ثمن البيع فى شراء سندات لصالح صندوق تمويل مشروعات الإسكان الاقتصادى وذلك دون الإخلال بأية التزامات أخرى يفرضها القانون رقم 107 لسنة 1976 .$m247$,'083408bb4c862e359bf53cdc9448db57'),
(69,0,$m247$المادة 69$m247$,$m247$يجب أن يرفق بمستندات طلب الموافقة أو الترخيص بالبناء بيان موقع من المالك أو من ينيبه يبين فيه ما إذا كان البناء كله أو بعضه بقصد التمليك أو التأجير ، وإذا صدرت الموافقة أو الترخيص بالبناء على أساس تأجير المبنى كله أو بعضه وجب على الطالب أن يقوم بتأجير عدد من الوحدات لا يقل عن العدد الذى صدرت الموافقة بالترخيص بالبناء على أساسه وذلك دون إخلال بحق المالك فى التصرف فى العقار كله أو بعضه وفقا للقواعد العامة .$m247$,'97d619d349c2ace783290fd8b8a9039c'),
(70,0,$m247$المادة 70$m247$,$m247$يحظر على المرخص لهم بإقامة مبان أو أجزاء منها بقصد التمليك الاستفادة من النظم أو الميزات الخاصة بتوزيع أو صرف أو تيسير الحصول على مواد البناء وذلك فى حدود ما رخص لهم فى إنشائه بقصد التمليك .
ويتولى ملاك هذه المبانى بمعرفتهم وعلى نفقتهم استيراد ما يلزم لها من مواد البناء ، أو شرائها من المواد المستوردة ، أو من المواد المنتجة محليا بالأسعار العالمية وذلك بعد الوفاء باحتياجات الإسكان المخصص للتأجير .
ويستثنى من ذلك أجهزة الدولة وشركات القطاع العام والجمعيات التعاونية وصناديق التأمين الخاصة .$m247$,'fdc19ec002a017f530b2c8def8010c7f'),
(71,0,$m247$المادة 71$m247$,$m247$يحظر على كل من تعاقد على تمليك أو تأجير وحدات سكنية قبل العمل بهذا القانون أو تعاقد على ذلك بعد العمل به أن يتراخى عمدا عن استكمال الوحدات المبيعة أو المؤجرة فى المواعيد المتفق عليها أو يعمد إلى تعطيل الانتفاع بها واستعمالها فيما أعدت له من أغراض .$m247$,'a6ad809f7628a9cd93633bb1721818e8'),
(72,0,$m247$المادة 72$m247$,$m247$تملك المساكن الشعبية الاقتصادية والمتوسطة التى أقامتها المحافظات وتم شغلها قبل تاريخ العمل بهذا القانون ، نظير أجرة تقل عن الأجرة القانونية ، إلى مستأجريها على أساس سداد الأجرة المخفضة لمدة خمس عشرة سنة وذلك وفقا للقواعد والشروط والأوضاع التى يصدر بها قرار من رئيس مجلس الوزراء .$m247$,'bc9d89d6eb0d3489e8b576e9aab9f504'),
(73,0,$m247$المادة 73$m247$,$m247$إذا زادت طبقات المبنى أو شققه على خمس وجاوز عدد ملاكها خمسة أشخاص قام بقوة القانون اتحاد الملاك المنصوص عليه فى المادة (862) من القانون المدنى وفى تطبيق هذا الحكم يعتبر ملاك الطبقة أو الشقة الواحدة مالكا واحدا ولو تعددوا .
ويكون البائع للعقار بالتقسيط عضوا فى الاتحاد حتى تمام الوفاء بكامل أقساط الثمن ، كما يكون المشترى بعقد غير مسجل عضوا فى الاتحاد .$m247$,'664a59d185bfd003cd6c812ada201add'),
(74,0,$m247$المادة 74$m247$,$m247$يصدر وزير الإسكان والتعمير بقرار منه نظاما نموذجيا لاتحادات ملاك العقارات لضمان الانتفاع بالأجزاء المشتركة بالعقار وحسن إدارتها .
ويتضمن النظام كيفية سير العمل بالاتحاد وقواعد تحديد التزامات وواجبات أعضائه وتنظيم استعمالهم لحقوقهم ، وقواعد تمثيل ملاك الطبقة أو الشقة أو بائع العقار إذا تعددوا وبيان أحوال استحقاق أجر مأمور الاتحاد وقواعد تحديده .
وعلى اتحادات ملاك العقارات القائمة وقت العمل بهذا القانون أن تعدل أوضاعها بما يتفق مع أحكامه وذلك خلال ستة أشهر من تاريخ العمل بالقرار المشار إليه فى هذه المادة .
ويسرى حكم الفقرة السابقة على المبانى القائمة التى لم يتكون بها اتحادات ملاك العقارات والتى تتوافر فيها الشروط المنصوص عليها فى المادة السابقة .$m247$,'3d59b868d947ecdd9a6903651ea33edc'),
(75,0,$m247$المادة 75$m247$,$m247$تتولى الوحدة المحلية المختصة مراقبة قيام الاتحادات المبينة فى هذا القانون ، والإشراف على أعمالها ويكون لها على الأخص ما يلى :
(أ) قيد الاتحاد وبيان أسماء أعضائه وممثله القانونى .
(ب) دعوة الاتحاد إلى الاجتماع لمباشرة أعماله .
(ج) تعيين مأمور مؤقت للاتحاد إلى أن يتم اختياره أو تعيينه وفقا لأحكام القانون المدنى .
(د) منح المأمور كل أو بعض سلطات الاتحاد إذا قصر أو تراخى فى القيام بواجباته .
(هـ) فحص الشكاوى والتظلمات التى تقدم من ذوى الشأن فى قرارات الاتحاد أو تصرفات المأمور وإبداء الرأى للاتحاد فى شأنها لإعادة النظر فيها إذا اقتضى الأمر ذلك .$m247$,'2f4ab71e89b8b336a194eb58c3fc0df6'),
(76,0,$m247$المادة 76$m247$,$m247$يعاقب بالحبس مدة لا تقل عن شهر ولا تزيد على ستة أشهر وبغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين كل من يخالف أحكام المواد 7/1 ، 8 ، 13 ، 24/1 ، 25 من هذا القانون .
ويحكم فضلا عن ذلك فى حالة مخالفة حكم المادة (8/1) بإنهاء عقد المسكن أو المساكن المحتجزة بالمخالفة لحكم القانون .$m247$,'fe64f7586c07726e7bc8a2b8e9dde670'),
(77,0,$m247$المادة 77$m247$,$m247$يعاقب كل من يخالف حكم المادة 26 من هذا القانون سواء كان مؤجرا أو مستأجرا أو وسيطا بالحبس مدة لا تقل عن ثلاثة أشهر وبغرامة تعادل مثلى المبلغ الذى تقاضاه بالمخالفة لأحكام هذه المادة ، ويعفى من العقوبة كل من المستأجر والوسيط إذا أبلغ أو بادر بالاعتراف بالجريمة .
وفى جميع الأحوال يجب الحكم على المخالف بأن يرد إلى صاحب الشأن ما تقاضاه على خلاف أحكام المادة المشار إليها .$m247$,'ff3d13ccc12e35a76de59fee8d40131f'),
(78,0,$m247$المادة 78$m247$,$m247$يعاقب بالحبس مدة لا تقل عن شهر وبغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين كل من خالف أحكام المواد 39 ، 40 ، 41 من هذا القانون .
وتكون العقوبة الحبس مدة لا تقل عن شهر ولا تجاوز ستة أشهر وبغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين فى حالة مخالفة أحكام المواد 38 ، 52/1 ، 53/1 ، 54/1 ، 54/2 من هذا القانون .$m247$,'9408aa72b10b2e4f9bae120e54954267'),
(79,0,$m247$المادة 79$m247$,$m247$يعاقب بالحبس مدة لا تقل عن شهرين ولا تزيد على سنة وبغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين كل من خالف أحكام المادتين 60/1 ، 64 من هذا القانون ، فإذا ترتب على عدم تنفيذ المالك لقرار صادر بالهدم الكلى أو الجزئى سقوط المبنى كانت العقوبة الحبس .$m247$,'8bf9d0c47a12a104adf52c3c35f34b5f'),
(80,0,$m247$المادة 80$m247$,$m247$يعاقب على مخالفة أحكام المواد 3/1 ، 69 ، 70/1 ، 71/1 بالحبس مدة لا تقل عن ثلاثة أشهر ولا تجاوز سنة وبغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين .
ويحكم فضلا عن ذلك فى حالة مخالفة المادة 69 بغرامة تعادل التكلفة التقديرية للوحدات المبيعة .
كما يحكم فى حالة مخالفة أحكام المادتين 3/1 ، 70/1 بأن يرد المخالف للدولة مبلغا يماثل ثمن المواد التى حصل عليها بالمخالفة لأحكام هاتين المادتين .$m247$,'88e10e12d5eb16ebaa030f8e1c292ac7'),
(81,0,$m247$المادة 81$m247$,$m247$يعاقب بالحبس مدة لا تقل عن شهر وبغرامة لا تقل عن مائة جنيه ولا تجاوز ثلاثمائة جنيه كل من يقوم عمدا بأى فعل من شأنه تهديد سلامة مبنى أو تعريضه للسقوط أو إتلافه كليا أو جزئيا إذا كان ذلك بقصد التوصل إلى اعتباره آيلا للسقوط .$m247$,'67a32dbe8ec0f97e93b45ff41cef5afe'),
(82,0,$m247$المادة 82$m247$,$m247$يعاقب بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن خمسمائة جنيه ولا تجاوز ألفى جنيه أو بإحدى هاتين العقوبتين ، كل من أجر مكانا أو جزءا منه أو باعه ، ولو بعقد غير مشهر ، أو مكن آخر منه وكان ذلك التأجير أو البيع أو التمكين على خلاف مقتضى عقد سابق ، ولو غير مشهر ، صادر منه أو من نائبه أو من أحد شركائه أو تابعيهم ، ويفترض علم هؤلاء بالعقد السابق الصادر من أيهم .
ويعاقب بالعقوبة السابقة من يسبق إلى وضع يده ، أو يشرع فى ذلك على خلاف مقتضى العقد السابق عليه ، قبل استصدار حكم بأفضليته من القضاء المختص ، ويفترض علم هذا المتعرض بالتعاقد السابق إذا كان زوجا لمن تعاقد معه أو من مكنه ، أو كان من أصوله أو فروعه أو من أقاربه أو أصهاره إلى الدرجة الرابعة .$m247$,'b765539ef0157ffe1f0d951f5d77ee83'),
(83,0,$m247$المادة 83$m247$,$m247$لا تخل العقوبات الواردة فى هذا القانون بأية عقوبة أشد منصوص عليها فى أى قانون آخر .$m247$,'f5b5da52433406d2705073c6c822a66a'),
(84,0,$m247$المادة 84$m247$,$m247$تؤول حصيلة جميع الغرامات التى يقضى بها تنفيذا لأحكام هذا القانون إلى صندوق تمويل مشروعات الإسكان الاقتصادى .$m247$,'e64645040cf9ffe31d009f9d813a2555'),
(85,0,$m247$المادة 85$m247$,$m247$تستمر المحاكم فى نظر الدعاوى التى أقيمت قبل العمل بهذا القانون طبقا للقواعد والإجراءات السارية قبل نفاذه .$m247$,'067938aba3c57f83bd1f9ba359160d3a'),
(86,0,$m247$المادة 86$m247$,$m247$يلغى القانون رقم 52 لسنة 1969 وأوامر نائب الحاكم العسكرى العام رقما 4 ، 5 لسنة 1976 ورقم 5 لسنة 1977 ، كما يلغى كل حكم يخالف أحكام هذا القانون .$m247$,'01e7b282a965218ee8a22f3d5535a5a4'),
(87,0,$m247$المادة 87$m247$,$m247$يصدر وزير الإسكان والتعمير اللوائح والقرارات اللازمة لتنفيذ هذا القانون خلال ثلاثة أشهر من تاريخ العمل به .$m247$,'319d39b7b3b56ca7a619cf73660c8c89'),
(88,0,$m247$المادة 88$m247$,$m247$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به من اليوم التالى لتاريخ نشره .$m247$,'ae1ca224d7e2797691b06d55d9fd8f82');

INSERT INTO m247_ver VALUES
(0,0,1,$m247$قانون رقم 49 لسنة 1977 فى شأن تأجير وبيع الأماكن وتنظيم العلاقة بين المؤجر والمستأجر
باسم الشعب
رئيس الجمهورية
قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m247$,'61ced0d78da8c78beadcce60973c52ee',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(1,0,1,$m247$فيما عدا الأراضى الفضاء تسرى أحكام هذا الباب على الأماكن وأجزاء الأماكن على اختلاف أنواعها المعدة للسكنى أو لغير ذلك من الأغراض سواء كانت مفروشة أو غير مفروشة مؤجرة من المالك أو من غيره وذلك فى عواصم المحافظات والبلاد المعتبرة مدنا بالتطبيق لأحكام القانون رقم 52 لسنة 1975 بإصدار قانون نظام الحكم المحلى والقوانين المعدلة له .
ويجوز بقرار من وزير الإسكان والتعمير مد نطاق سريان أحكامه كلها أو بعضها على القرى بناء على اقتراح المجلس المحلى للمحافظة وكذلك على المناطق السكنية التى لا ينطبق عليها قانون نظام الحكم المحلى المشار إليه ، ولا يكون لهذا القرار أثر على الأجرة المتعاقد عليها قبل صدوره .$m247$,'75ad3fc0e09a032822d8aaea92d0b672',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(2,0,1,$m247$لا تسرى أحكام هذا الباب على :
(أ) المساكن الملحقة بالمرافق والمنشآت وغيرها من المساكن التى تشغل بسبب العمل .
(ب) المساكن التى تشغل بتصاريح أشغال مؤقتة لمواجهة حالات الطوارئ والضرورة ويصدر تحديد تلك الحالات وشروط الانتفاع بهذه المساكن قرار من وزير الإسكان والتعمير .$m247$,'7802921828e5386f6ec618e3cb4915c2',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(3,0,1,$m247$يحظر على المرخص لهم فى إقامة مبان أو أجزاء منها من المستوى الفاخر ، الاستفادة من النظم أو الميزات الخاصة بتوزيع أو صرف أو تيسير الحصول على مواد البناء .
ويتولى ملاك هذه المبانى بمعرفتهم وعلى نفقتهم استيراد ما يلزم لها من مواد البناء أو شرائها من المواد المستوردة أو من المواد المنتجة محليا بالأسعار العالمية بعد الوفاء باحتياجات المستويات الأخرى من الإسكان .$m247$,'15a254b3d8588cec64e6a338f74559b3',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(4,0,1,$m247$تسرى أحكام هذا الباب على الأماكن التى ينشئها ، اعتبارا من تاريخ العمل بهذا القانون ، مستأجرو الأراضى الفضاء على هذه الأراضى بترخيص كتابى من مالكها متى توافرت الشروط الآتية :
(أ) أن يكون الترخيص تاليا لتاريخ العمل بهذا القانون .
(ب) أن تكون المبانى شاغلة لنسبة مقدارها خمسون فى المائة (50%) على الأقل من الحد الأقصى المسموح بالارتفاع به مسطحا وارتفاعا وفقا لأحكام قانون توجيه وتنظيم أعمال البناء .
(ج) ألا يقل مسطح المبانى المخصصة للسكنى عن ثلاثة أرباع مجموع مسطحات المبانى .
وإذا انتهى عقد إيجار الأرض الفضاء لأى سبب من الأسباب استمر من أنشأ الأماكن المقامة عليها أو من استأجرها منه بحسب الأحوال شاغلا لهذه الأماكن بالأجرة المحددة قانونا .$m247$,'d83221227320a3dc2ed74ca1299d6725',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(5,0,1,$m247$تختص المحاكم العادية دون غيرها بالفصل فى المنازعات التى تنشأ عن تطبيق أحكام هذا القانون .$m247$,'8846c3000b3d6b6d5ec7fe281e19bdb6',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(6,0,1,$m247$يعد فى حكم المستأجر فى تطبيق أحكام هذا الباب مالك العقار المنزوعة ملكيته بالنسبة إلى ما يشغله من هذا العقار .
وتعتبر الأماكن الصادر فى شأنها قرارات استيلاء لشغلها مؤجرة إلى الجهات التى تم الاستيلاء لصالحها .$m247$,'dbd7a590af4069c5386a8bea0bf863ac',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(7,0,1,$m247$للعامل المنقول إلى بلد بدلا من عامل آخر فى ذات جهة العمل حق الأولوية على غيره فى استئجار المسكن الذى كان يشغله هذا العامل إذا قام بإعلان المؤجر فى مدى أسبوعين على الأكثر من تاريخ الإخلاء برغبته فى ذلك بكتاب موصى عليه مصحوب بعلم الوصول على أن يعزز ذلك عن طريق الجهة التى يعمل بها المتبادلان ، ويحظر على المالك التعاقد قبل انقضاء هذه المدة .
وعلى العامل المنقول إلى بلد آخر أن يخلى المسكن الذى كان يشغله بمجرد حصوله على مسكن فى البلد المنقول إليه ، إلا إذا قامت ضرورة ملجئة تمنع من إخلاء مسكنه .
وفى البلد الواحد يجوز تبادل الوحدات السكنية بين مستأجر وآخر وذلك […] البلاد و بين الأحياء ، وطبقا للحالات ووفقا للقواعد والشروط والإجراءات والضمانات التى يحددها قرار من وزير الإسكان والتعمير .$m247$,'cfc3ffbb06499a265c4b185708e3792e',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(8,0,1,$m247$لا يجوز للشخص أن يحتجز فى البلد الواحد أكثر من مسكن بلا مقتض .
ولا يجوز إبقاء المساكن المعدة للاستغلال خالية مدة تزيد على أربعة أشهر إذا قدم لاستئجارها مستأجر بالأجرة القانونية .
ويعتبر فى حكم إبقاء المساكن خالية التراخى عمدا عن إعدادها للاستغلال ، وفى هذه الحالة يجوز للمحافظ المختص التنبيه على المالك بكتاب موصى عليه بعلم وصول لإعداد البناء للاستغلال فى المهلة التى يحددها له ، فإذا انقضت هذه المهلة دون ذلك كان للمحافظ أن يعهد إلى إحدى الجهات القيام بإعداد البناء للاستغلال على حساب المالك وفقا للقواعد التى يصدر بها قرار من وزير الإسكان والتعمير ، ويكون للمبالغ المستحقة لهذه الجهة حق امتياز على المبنى الذى قامت باستكماله من ذات مرتبة الامتياز المقرر بالمادة (1148) من القانون المدنى .
ويكون للجهة المشار إليها تأجير وحدات المبنى التى لم يسبق تأجيرها واقتضاء أجرة وحدات المبنى جميعه إلى أن تستوفى المبالغ التى أنفقتها والمصروفات الإدارية ، ويحق للمالك أن يحصل على 20% من تلك الأجرة شهريا .$m247$,'fd0810c0d62bdfc46a1177b6fbb452e7',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(9,0,1,$m247$يستمر العمل بالأحكام المحددة للأجرة والأحكام المقررة على مخالفتها بالقانون رقم 121 لسنة 1947 بشأن إيجار الأماكن وتنظيم العلاقات بين المؤجرين والمستأجرين والقانون رقم 169 لسنة 1961 بتقرير بعض الإعفاءات من الضريبة على العقارات المبنية وخفض الإيجارات بمقدار الاعفاءات ، والقانون رقم 46 لسنة 1962 بتحديد إيجار الأماكن والقانون رقم 7 لسنة 1965 فى شأن تخفيض إيجار الأماكن والقانون رقم 52 لسنة 1969 فى شأن إيجار الأماكن وتنظيم العلاقة بين المؤجرين والمستأجرين والقوانين المعدلة لها ، وذلك بالنسبة إلى نطاق سريان كل منها .$m247$,'4e1f76b753697758c77ae4c1bd9776c7',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(10,0,1,$m247$يجب على من يرغب فى إقامة مبنى أن يرفق بطلب الترخيص له بالبناء المقدم إلى الجهة الإدارية المختصة بشئون التنظيم بيانا بقيمة الأرض والمبانى ومواصفات البناء ومقترحاته عن أجرة المبنى وتوزيعها على وحداته وما يدل على أداء مبلغ 500 قرش عن كل وحدة من هذه الوحدات ، ويحتسب هذا المبلغ ضمن تكاليف المبنى وتخصص حصيلة هذا المبلغ للاتفاق منه على أغراض لجنة تحديد الإيجارات أو الطعن فى قراراتها وفقا للنظام الذى يصدر به قرار من وزير الإسكان والتعمير .
وتكون البيانات المشار إليها والموضحة باللائحة التنفيذية متممة للمستندات اللازمة للحصول على الترخيص المشار إليه طبقا لأحكام القانون رقم 106 لسنة 1976 فى شأن توجيه وتنظيم أعمال البناء والقرارات المنفذة له .$m247$,'3d789e804e73dc6a90e73d2ad631938c',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(11,0,1,$m247$يتضمن قرار الجهة الإدارية المختصة بشئون التنظيم بالموافقة على إقامة البناء تقدير الأجرة الإجمالية للمبنى وفقا للأحكام الواردة فى هذا الباب وتوزيعها على وحدات المبنى وصرف ترخيص البناء موضحا به قرار التقدير والتوزيع وعلى أساسه يتم التعاقد بين المؤجر والمستأجر على أن يتم تحديد الأجرة طبقا لأحكام هذا الباب .
ويكون التقدير المبدئى للأجرة وفقا للقرارات التى يصدرها وزير الإسكان والتعمير فى شأن تحديد مستويات ومواصفات المبانى وأسس تكاليفها التقديرية وفقا لأحكام القانون رقم 106 لسنة 1976$m247$,'6aae77f9a3dfaebe9930eb66b0e525b6',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(12,0,1,$m247$تتولى تحديد أجرة الأماكن الخاضعة لأحكام هذا القانون وتوزيعها على وحداته لجان يصدر بتشكيلها قرار من المحافظ المختص من اثنين من المهندسين المعماريين أو المدنيين المقيدين بنقابة المهندسين ومن جهتين مختلفتين وأحد العاملين المختصين بربط أو تحصيل الضريبة على العقارات المبنية وعضوين يختارهما المجلس المحلى المختص من غير أعضائه أحدهما من الملاك والآخر من المستأجرين ، وتكون رئاستها للأقدم من المهندسين ، ويشترط لصحة انعقادها حضور أحد المهندسين والعضو المختص بربط أو تحصيل الضريبة وأحد العضوين المختارين ، وتصدر قرارات اللجنة بأغلبية أصوات الحاضرين وعند التساوى يرجح رأى الجانب الذى منه الرئيس .
ويؤدى أعضاء اللجان قبل مباشرة أعمالهم يمينا أمام المحافظ بأن يؤدوا أعمالهم بصدق وأمانة .
ويصدر وزير الإسكان والتعمير قرارا بالقواعد والإجراءات التى تنظم أعمال هذه اللجان وطريقة إخطار ذوى الشأن بقراراتها الصادرة فى شأن تحديد الأجرة .$m247$,'75f0c6cfe2ff009eade69e4203b081dd',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(13,0,1,$m247$على مالك البناء فى موعد لا يجاوز ثلاثين يوما من تاريخ نفاذ أول عقد لإيجار أية وحدة من وحدات المبنى أو من تاريخ شغلها لأول مرة بأية صورة من صور الأشغال أن يخطر اللجنة المشار إليها فى المادة السابقة والتى يقع فى دائرتها المبنى لتقوم بتحديد أجرته وتوزيعها على وحداته بعد مراجعة ما تم إنجازه ومطابقته للمواصفات الصادر على أساسها موافقة لجنة توجيه استمارات أعمال البناء ، وترخيص المبانى .
وللمستأجر أن يخطر اللجنة المذكورة بشغله المكان المؤجر بكتاب موصى عليه .
وتنظم اللائحة التنفيذية إجراءات إخطار المالك والمستأجر للجنة .
ويجوز للجنة أن تقوم بالتقدير من تلقاء نفسها أو بناء على إخطار من الجهة المختصة بحصر العقارات المبنية .
ويلتزم المالك بتسليم العين المؤجرة صالحة للاستعمال فى المواعيد المتفق عليها وإلا جاز للمستأجر بعد إعذار المالك استكمال الأعمال الناقصة بترخيص من قاضى الأمور المستعجلة مع خصم التكاليف من الأجرة .$m247$,'e14f869f9a40fcf8a3211a457b1502bb',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(14,0,1,$m247$تقدر أجرة المبنى المرخص فى إقامته من تاريخ العمل بهذا القانون على الأسس التالية :
(أ) صافى عائد استثمار العقار بواقع 7% (سبعة فى المائة) من قيمة الأرض والمبانى .
(ب) مقابل استهلاك رأس المال ومصروفات الإصلاحات والصيانة والإدارة بواقع 3% (ثلاثة فى المائة) من قيمة المبانى .
ومع مراعاة الإعفاءات المقررة فى شأن الضريبة على العقارات المبنية يضاف إلى الأجرة المحددة وفقا لما تقدم ما يخصها من الضرائب العقارية الأصلية والإضافية كل ذلك مع عدم الإخلال بأحكام القوانين الأخرى الخاصة بالتزامات كل من المؤجرين والمستأجرين بشأن الضرائب والرسوم .
ويلتزم المستأجر بأداء هذه الضرائب والرسوم إلى المؤجر مع الأجرة الشهرية ويترتب على عدم الوفاء بها نفس النتائج المترتبة على عدم سداد الأجرة .$m247$,'c738f8f5a608e005087d81001668ae9c',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(15,0,1,$m247$يكون تحديد أجرة المبانى بعد إنشائها على أساس تقدير قيمة الأرض وفقا لثمن المثل فى عام 1974 مع زيادة سنوية مقدارها 7% (سبعة فى المائة) لحين البناء ، وتقدير قيمة المبانى وفقا للتكلفة الفعلية وقت البناء ، وذلك دون التقيد بالأجرة المبدئية المقدرة للمبنى قبل إنشائه مع الالتزام بمستوى المبانى المبين بالموافقة الصادر على أساسها ترخيص البناء ودون اعتداد بأية زيادة فى المواصفات أثناء التنفيذ .
وتحسب كامل قيمة الأرض والمبانى والأساسات والتوصيلات الخارجية للمرافق العامة فى حالة البناء على كل المساحة المسموح بالبناء عليها واستيفاء الارتفاع طبقا للقيود المفروضة على المنطقة وأحكام قانون توجيه وتنظيم أعمال البناء وغيره من القوانين واللوائح .
أما فى حالة البناء على كل المساحة المسموح بالبناء عليها مع عدم استكمال المبنى الحد الأقصى المسموح به لارتفاع البناء تحسب كل قيمة المبانى المنشأة كما تحسب قيمة الأرض والأساسات والتوصيلات الخارجية للمرافق بنسبة ما يقام فعلا من أدوار إلى العدد الكلى للأدوار التى تسمح بها قيود الارتفاع المشار إليها ، ويجوز فى بعض المناطق تعديل هذه النسبة بما يتفق وصقع الموقع وظروف العمران وذلك بقرار من المجلس المحلى المختص .
وإذا كان البناء لا يشغل غير جزء من الأرض المسموح بالبناء عليها فلا يحسب فى تقدير الإيجار من قيمة الأرض إلا القدر المخصص لمنفعة البناء فقط بشرط تحديد هذا القدر بفواصل ثابتة وإلا فلا تحسب سوى المساحة المبنى عليها بالفعل .$m247$,'aa4f571379c510f853ec18c58228712c',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(16,0,1,$m247$يعاد تقدير قيمة الأرض عند تحديد الأجرة فى حالة تعلية البناء وذلك إذا تمت التعلية بعد سنتين على الأقل من تاريخ إنشاء المبانى الأصلية أو فى حالة ما إذا طرأ على العقار ما يستوجب تطبيق أحكام القوانين السارية فى شأن مقابل التحسين وفى هذه الحالة تكون إعادة تقدير قيمة الأرض بقصد تحديد أجرة المبانى المستجدة فقط .$m247$,'72083910bef5acf2b02901a1b0c359bb',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(17,0,1,$m247$تكون قرارات لجان تحديد الأجرة نافذة رغم الطعن عليها ، وتعتبر نهائية إذا لم يطعن عليها فى الميعاد .$m247$,'7d35f6d085a944a57620d2415f303070',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(18,0,1,$m247$يكون الطعن على قرارات لجان تحديد الأجرة خلال ثلاثين يوما من تاريخ الإخطار بصدور قرار اللجنة أمام المحكمة الابتدائية الكائن فى دائرتها المكان المؤجر ويلحق بتشكيلها مهندس معمارى أو مدنى مقيد بنقابة المهندسين من الدرجة الثانية على الأقل ومن غير القائمين بتحديد الأجرة يختاره المحافظ لمدة سنتين قابلة للتجديد ولا يكون له صوت معدود فى المداولة .
ويحلف المهندس يمينا أمام إحدى دوائر الاستئناف المختصة بأن يؤدى عمله بصدق وأمانة .$m247$,'bfb7c2ec9410be213b1089ed71f1d57d',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(19,0,1,$m247$على قلم كتاب المحكمة إخطار جميع المستأجرين لباقى وحدات المبنى بالطعن وبالجلسة المحددة لنظره وذلك بكتاب موصى عليه مصحوب بعلم الوصول .
ويترتب على قبول الطعن إعادة النظر فى تقدير أجرة باقى الوحدات التى شملها قرار لجنة تحديد الأجرة ويعتبر الحكم الصادر فى الطعن ملزما لكل من المالك والمستأجرين .$m247$,'f84d1a920240cc727c2f255f8f7bd595',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(20,0,1,$m247$لا يجوز الطعن فى الحكم الصادر من المحكمة المشار إليها فى المادة (18) إلا لخطأ فى تطبيق القانون .
ويكون الطعن أمام محكمة الاستئناف خلال ثلاثين يوما من تاريخ صدور الحكم وذلك بصحيفة تقدم إلى قلم كتاب المحكمة — يوضح بها أسماء الخصوم ومحال إقامتهم وتاريخ الحكم المطعون عليه وأوجه الطعن .
ويكون حكمها غير قابل للطعن فيه بأى وجه من أوجه الطعن .$m247$,'baded39f267e9e7b32e3b60b473ec13e',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(21,0,1,$m247$إذا لم تكن العين مؤجرة وقت صدور قرار لجنة تحديد الأجرة ، جاز لأول مستأجر لها أن يطعن على هذا القرار خلال ثلاثين يوما من تاريخ نفاذ عقده .
وفى هذه الحالة يقتصر أثر الحكم الصادر فى الطعن على أجرة الوحدة التى يشغلها الطاعن وحدها دون باقى وحدات المبنى .$m247$,'a6d1eb42e239630cf32b40f166dee798',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(22,0,1,$m247$يلتزم المستأجر فى حالة تحديد الأجرة بالزيادة عما هو منصوص عليه فى العقد ، بأداء الفرق مقسطا على أقساط شهرية لمدة مساوية للمدة التى استحق عنها أو بسداده كاملا إذا أراد إخلاء العين المؤجرة قبل انقضاء المدة المذكورة .
وعلى المؤجر أن يرد إلى المستأجر فرق الأجرة عند تحديدها بما يقل عما هو منصوص عليه فى العقد وبالطريقة المنصوص عليها فى الفقرة السابقة .$m247$,'253259e9130a9f7caaf6005b776a61df',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(23,0,1,$m247$فى جميع الأحوال التى يتم فيها تغيير استعمال العين المؤجرة بعد تاريخ العمل بهذا القانون وبموافقة المالك إلى غير أغراض السكنى تزاد الأجرة القانونية بنسبة 200% للمبانى المنشأة قبل أول يناير سنة 1944 ، 100% للمبانى المنشأة منذ أول يناير سنة 1944 وقبل 5 نوفمبر سنة 1961 ، 75% للمبانى المنشأة منذ 5 نوفمبر سنة 1961 حتى تاريخ العمل بهذا القانون ، 50% للمبانى التى يرخص فى إقامتها اعتبارا من تاريخ العمل بهذا القانون .$m247$,'489a8c765faf35edbb8449275e654536',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(24,0,1,$m247$اعتبارا من تاريخ العمل بأحكام هذا القانون تبرم عقود الإيجار كتابة ويجب إثبات تاريخها بمأمورية الشهر العقارى الكائن بدائرتها العين المؤجرة .
ويلزم المؤجر عند تأجير أى مبنى أو وحدة منه أن يثبت فى عقد الإيجار تاريخ ورقم وجهة إصدار ترخيص البناء ومقدار الأجرة المقدرة للوحدة المؤجرة وفقا للمادة (11) من هذا القانون ، وذلك بالنسبة للمبانى الخاضعة لنظام الأجرة المبدئية .
ويجوز للمستأجر إثبات واقعة التأجير وجميع شروط العقد بكافة طرق الإثبات .
ويحظر على المؤجر إبرام أكثر من عقد إيجار واحد للمبنى أو الوحدة منه وفى حالة المخالفة يقع باطلا العقد أو العقود اللاحقة للعقد الأول .$m247$,'617302d81ab6d7b22eee43b74cbe38e3',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(25,0,1,$m247$لا يجوز أن يزيد مقدار التأمين الذى يدفعه المستأجر على ما يعادل أجرة شهرين ويسرى هذا الحكم على عقود الإيجار القائمة وقت العمل بهذا القانون وللمستأجر الحق فى استرداد الزيادة فى قيمة التأمين بخصمها مباشرة من الأجرة مقسطة على سنة أو حتى نهاية العقد أو عند إخلاء العين المؤجرة أيهما أقرب وذلك بغير حاجة إلى الالتجاء إلى القضاء .$m247$,'7db630cdeaa0353b2aa698fe88e32ba4',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(26,0,1,$m247$لا يجوز للمؤجر مالكا كان أو مستأجرا بالذات أو بالوساطة اقتضاء أى مقابل أو أتعاب بسبب تحرير العقد أو أى مبلغ إضافى خارج نطاق عقد الإيجار زيادة على التأمين والأجرة المنصوص عليها فى العقد .
كما لا يجوز بأية صورة من الصور للمؤجر أن يتقاضى أى مقدم إيجار .$m247$,'7dc8e761607e4479457f997ff43c4432',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(27,0,1,$m247$يجب أن يتم الوفاء بالأجرة المحددة وما فى حكمها كاملة إلى المؤجر طبقا لأحكام هذا الباب فى موعد لا يجاوز الأسبوع الأول من الشهر المستحقة عنه أو الموعد المتفق عليه فى العقد وذلك بإيصال مثبتا فيه قيمة الأجرة .
فإذا امتنع المؤجر عن استلام الأجرة وإعطاء سند المخالصة عنها ، فللمستأجر قبل مضى 15 (خمسة عشر) يوما من تاريخ الاستحقاق أن ينذر المؤجر بكتاب موصى عليه مصحوب بعلم وصول لتسلمها خلال أسبوع ، فإذا لم يتسلمها خلال هذا الميعاد يودع المستأجر الأجرة بدون رسوم خلال الأسبوع التالى بخزانة مأمورية العوائد المختصة .
وفى المدن والقرى التى لا توجد بها مأموريات عوائد ، يتم الإيداع بخزينة الوحدة المحلية الواقع فى دائرتها العقار .
وعلى كل من المستأجر والجهة المودع لديها الأجرة إخطار المؤجر بهذا الإيداع بكتاب موصى عليه مصحوب بعلم وصول .
ومع عدم المساس بما يكون للمؤجر من حقوق أخرى يعتبر إيصال الإيداع سندا لإبراء ذمة المستأجر من قيمة الأجرة المستحقة بالقدر المودع .
وعلى الجهة المودع لديها الأجرة أداء الأجرة المودعة للمؤجر فور طلبها دون قيد أو شرط أو إجراءات .$m247$,'bfe7733048bad142ed00f95748bca2fb',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(28,0,1,$m247$لا يجوز حرمان المستأجر من أى حق من حقوقه أو منعه من أية ميزة كان يتمتع بها .
ولقاضى الأمور المستعجلة أن يأذن للمستأجر فى هذه الحالة بإعادة الحق أو الميزة على حساب المؤجر خصما من الأجرة المستحقة وذلك بعد إعذار المؤجر بإعادتها إلى ما كانت عليه فى وقت مناسب .
ويجوز للجهة التى تحدد بقرار من المحافظ القيام بتنفيذ الأعمال اللازمة لإعادة الحق أو الميزة التى ألزم بها المالك بموجب الحكم الصادر فى هذا الشأن وذلك على نفقة المالك على أن تقتضى النفقات منه بالطريق الإدارى .
ومع ذلك إذا أصبح التزام المؤجر مرهقا أو غير متناسب مع ما يغله العقار من أجرة ، ففى هذه الحالة يجوز للقاضى أن يوزع تكلفة الإعادة على كل من المؤجر والمستأجر .
فإذا تبين عدم إمكان إعادة الحق أو الميزة ، جاز للمحكمة الابتدائية الواقع فى دائرتها العقار بناء على طلب المستأجر إنقاص الأجرة بما يقابل الحق أو الميزة .$m247$,'fbc928d86278754fccc211a857e7df10',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(29,0,1,$m247$مع عدم الإخلال بحكم المادة (8) من هذا القانون لا ينتهى عقد إيجار المسكن بوفاة المستأجر أو تركه العين إذا بقى فيها زوجه أو أولاده أو أى من والديه الذين كانوا يقيمون معه حتى الوفاة أو الترك وفيما عدا هؤلاء من أقارب المستأجر نسبا أو مصاهرة حتى الدرجة الثالثة يشترط لاستمرار عقد الإيجار إقامتهم فى المسكن مدة سنة على الأقل سابقة على وفاة المستأجر أو تركه العين أو مدة شغله للمسكن أيهما أقل .
إذا كانت العين مؤجرة لمزاولة نشاط تجارى أو صناعى أو مهنى أو حرفى فلا ينتهى العقد بوفاة المستأجر أو تركه العين ويستمر لصالح ورثته وشركائه فى استعمال العين بحسب الأحوال .
وفى جميع الأحوال يلتزم المؤجر بتحرير عقد إيجار لمن لهم حق فى الاستمرار فى شغل العين ويلتزم هؤلاء الشاغلون بطريق التضامن بكافة أحكام العقد .$m247$,'7a38b31403a3ea7502ffb4290234f52a',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(30,0,1,$m247$استثناء من حكم المادة (604) من القانون المدنى تسرى عقود الإيجار القائمة على المالك الجديد للعقار ولو لم يكن لسند الإيجار تاريخ ثابت بوجه رسمى سابق على تاريخ انتقال الملكية .$m247$,'3e5c291348a91ba96f4a971155468c10',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(31,0,1,$m247$فى غير الأماكن المؤجرة مفروشة لا يجوز للمؤجر أن يطلب إخلاء المكان ولو انتهت المدة المتفق عليها فى العقد إلا لأحد الأسباب الآتية :
(أ) إذا لم يقم المستأجر بالوفاء بالأجرة المستحقة خلال خمسة عشر يوما من تاريخ تكليفه بذلك بكتاب موصى عليه مصحوب بعلم الوصول دون مظروف أو بإعلان على يد محضر ولا يحكم بالإخلاء إذا قام المستأجر قبل إقفال باب المرافعة فى الدعوى بأداء الأجرة وكافة ما تكبده المؤجر من مصاريف ونفقات فعلية فإذا تكرر امتناع المستأجر أو تأخره فى الوفاء بالأجرة المستحقة دون مبررات تقدرها المحكمة حكم عليه بالإخلاء .
ولا ينفذ حكم القضاء المستعجل بطرد المستأجر من العين بسبب التأخير فى سداد الأجرة إعمالا للشرط الفاسخ الصريح إذا سدد المستأجر الأجرة والمصاريف والأتعاب عند تنفيذ الحكم .
(ب) إذا أجر المستأجر المكان المؤجر من الباطن أو تنازل عنه أو تركه للغير بأى وجه من الوجوه بغير إذن كتابى صريح من المالك للمستأجر الأصلى وذلك مع عدم الإخلال بأحكام المواد التى تجيز للمستأجر ذلك .
(ج) إذا استعمل المستأجر المكان المؤجر أو سمح باستعماله بطريقة تخالف شروط الإيجار المعقولة والمتعارف عليها وتضر بمصلحة المؤجر أو استعمله فى غير الأغراض المؤجر من أجلها ، وذلك بعد إعذاره بإعادة الحالة إلى ما كانت عليه .
(د) إذا استعمل المستأجر المكان المؤجر أو سمح باستعماله بطريقة ضارة بالصحة أو مقلقة للراحة أو منافية للآداب العامة متى ثبت ذلك بحكم قضائى نهائى .$m247$,'86411701c8bb4520dec013affd2d05f1',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(32,0,1,$m247$يجوز للمالك زيادة عدد الوحدات السكنية فى المبنى المؤجر بالإضافة أو التعلية ولو كان عقد الإيجار يمنع ذلك ولا يخل هذا بحق المستأجر فى إنقاص الأجرة إن كان لذلك محل .
ويجوز بحكم من قاضى الأمور المستعجلة الترخيص بإخلاء وهدم ما قد يعترض الإضافة أو التعلية من أجزاء الأماكن غير السكنية ، بشرط تعويض ذوى الشأن وإعطائهم حق العودة ، وفقا لأحكام الفصل الأول من الباب الثانى من هذا القانون .
أما إذا كان الجزء من المكان مخصصا للسكنى فلا يجوز الحكم بإخلائه وهدمه إلا إذا قام المالك بتدبير مسكن آخر مناسب وذلك دون الإخلال بحق المستأجر فى العودة إلى المبنى الجديد ، وفقا لأحكام الفصل الأول من الباب الثانى من هذا القانون .$m247$,'511d5d701390656cce2ccbc42269fe82',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(33,0,1,$m247$تكون قيمة استهلاك المياه على عاتق شاغلى الأماكن القائمة وقت العمل بهذا القانون أيا كان تاريخ إنشائها أو التى تقام بعد العمل به وفقا للقواعد الآتية :
(أ) قيمة ما تسجله العدادات الفرعية المركبة بوحداتهم إن وجدت عدادات بجميع وحدات المبنى ، وفى حالة عدم تساوى قراءة العداد الرئيسى مع مجموع قراءات العدادات الفرعية يوزع الفرق بالتساوى بين وحدات المبنى .
(ب) إذا لم توجد عدادات فرعية بأية وحدة من وحدات المبنى فتوزع قيمة استهلاك المياه التى يسجلها العداد الرئيسى على الشاغلين بحسب حجرات كل وحدة إلى عدد حجرات المبنى جميعه وتحسب الصالة حجرة واحدة ولو تعددت .
(ج) إذا وجدت عدادات فرعية ببعض وحدات المبنى دون البعض الآخر فتوزع قيمة استهلاك المياه التى يسجلها العداد الرئيسى بعد استنزال ما تسجله العدادات الفرعية على الشاغلين على الوجه المبين بالفقرة السابقة .
(د) فى الحالات التى يتم فيها توريد المياه عن غير طريق الجهة القائمة على ذلك يتحمل الشاغلون بقيمة استهلاك المياه وفقا لما يتم الاتفاق عليه بينهم وبين المؤجرين بما لا يجاوز 7% (سبعة فى المائة) من القيمة الإيجارية المحددة قانونا .
ويقع باطلا كل اتفاق يخالف القواعد سالفة الذكر .$m247$,'3596bb70c301bb60a761eeec2e7d0e9e',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(34,0,1,$m247$تخفض الأجرة الشهرية بمقدار (5%) خمسة فى المائة بحد أدنى مقداره مائتا مليم بالنسبة إلى شاغلى الأماكن الذين لم يكونوا ملتزمين بقيمة استهلاك المياه فى 18/8/1969 ، كما يسرى هذا الخفض إذا كان قد جرى العمل بين المؤجر والمستأجر على تحمل المؤجر بقيمة الاستهلاك على الرغم من النص فى عقد الإيجار على التزام المستأجر بها ، على ألا يسرى هذا الخفض بالنسبة إلى الأماكن التى أنشئت قبل أول يناير سنة 1944
ويجوز لكل من المالك أو المستأجر تركيب عداد خاص على نفقته لحساب استهلاك المياه بالوحدة المؤجرة ، وذلك دون اشتراط موافقة الآخر ، وفى هذه الحالة تتم المحاسبة وفقا للأوضاع المبينة فى المادة السابقة .$m247$,'f3110c76affcf675fc6140a852fa79ab',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(35,0,1,$m247$يلتزم ملاك المبانى التى تنشأ بعد تاريخ العمل بهذا القانون بتوفير التوصيلات اللازمة لتركيب عداد خاص بكل وحدة من وحدات المبنى بمعرفة المستأجر وعلى نفقته ويراعى بقدر الإمكان وضعه فى مكان تسهل معه قراءة العداد دون الحاجة إلى دخول الوحدة ذاتها .$m247$,'f2ba48ed382173aa7d1c1e5963e83bca',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(36,0,1,$m247$يصدر قرار من المحافظ المختص بتحديد وكيفية توزيع قيمة استهلاك المياه فى الحالات التى توجد فيها غرف خدمات ومنافع مشتركة أو حدائق أو مأوى أو جراجات أو محال عامة أو أماكن تمارس فيها صناعة أو تجارة أو ما شابه ذلك من أنشطة غير سكنية .$m247$,'c69ddad5f127db6dd48b16d568f0386d',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(37,0,1,$m247$فى جميع الحالات يلتزم المستأجر بأن يسدد قيمة استهلاك المياه إلى المؤجر فى المواعيد المحددة لسداد الأجرة ، أو كلما طلب المؤجر ذلك ، ما لم تضع الجهات الموردة للمياه أنظمة وقواعد لاقتضاء هذه القيمة من شاغلى المبانى مباشرة . وعلى المؤجر إثبات تقاضيه تلك القيمة بإيصال مستقل أو مع إيصال استلام الأجرة .
ويترتب على التأخير فى سداد قيمة استهلاك المياه المستحقة للمؤجر ما يترتب على التأخير فى سداد الأجرة من آثار .
وإذا ترتب على تأخر المؤجر فى أداء قيمة استهلاك المياه إلى الجهة الموردة لها قطعها عن المكان المؤجر أو الشروع فى ذلك كان للمستأجر أن يؤدى قيمة الاستهلاك إلى الجهة المذكورة مباشرة خصما مما يستحق للمؤجر لديه ، وذلك دون حاجة إلى أية إجراءات .$m247$,'c866a963c7638cc4669c114d425a85db',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(38,0,1,$m247$يلتزم ملاك المبانى المؤجرة كلها أو بعضها بأن يقوموا بعمل الخزانات وتركيب الطلمبات اللازمة لتوفير المياه لجميع أدوار المبنى ، وأن يستخدموا مواسير مياه ذات أقطار كافية تسمح بمرور القدر المناسب للاستهلاك ، وذلك فى المناطق ووفقا للقواعد والشروط التى يصدر بها قرار من المحافظ بعد أخذ رأى الجهات القائمة على مرفق المياه وإذا امتنع المالك من التنفيذ تطبق أحكام الفقرتين الثانية والثالثة من المادة (60) من هذا القانون دون حاجة إلى العرض على اللجنة أو المحكمة .
وتطبق أحكام المادة (61) بالنسبة إلى المبالغ التى ينفقها الملاك فى سبيل تنفيذ الالتزام المنصوص عليه بالفقرة السابقة .
ويحظر على شاغل العين تركيب طلمبة أو أى جهاز من شأنه ضخ المياه إلى الوحدة الخاصة به بالمخالفة للقواعد والشروط المقررة بمعرفة الجهة القائمة على مرفق المياه ، وفى حالة المخالفة تتم إزالة أسباب المخالفة إداريا وعلى نفقة المخالف فضلا عن العقوبة المقررة .$m247$,'176ed9ee67a8acedef2f4c7cde6330e3',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(39,0,1,$m247$لا يجوز للمالك فى غير المصايف والمشاتى المحددة وفقا لأحكام هذا القانون أن يؤجر سوى وحدة واحدة مفروشة فى العقار الذى يملكه وفى تطبيق هذه المادة يعتبر الشخص وزوجه وأولاده القصر مالكا واحدا .
واستثناء من ذلك يجوز للمالك أن يؤجر وحدة أخرى مفروشة فى أى من الأحوال أو الأغراض الآتية :
(أ) التأجير لإحدى الهيئات الأجنبية أو الدبلوماسية أو القنصلية أو المنظمات الدولية أو الإقليمية أو لأحد العاملين بها من الأجانب ، أو للأجانب المرخص لهم بالعمل أو الإقامة بجمهورية مصر العربية .
(ب) التأجير للسائحين الأجانب أو لإحدى الجهات المرخص لها فى مباشرة أعمال السياحة بغرض إسكان السائحين وذلك فى المناطق التى يصدر بتحديدها قرار من وزير السياحة بالاتفاق مع المحافظ المختص .
على أنه إذا اتخذت الملكية شكل وحدات مفرزة فى عقارات ، فإنه لا يكون للمالك فى هذه الحالة سوى تأجير وحدتين مفروشتين فى كل مدينة مهما تعددت الوحدات المملوكة له ، وذلك بنفس الشروط والأوضاع المبينة بهذه المادة .
كما يكون للمالك إذا أقام خارج الجمهورية بصفة مؤقتة أن يؤجر سكنه مفروشا أو خاليا وعليه فى هذه الحالة أن يخطر المستأجر لإخلاء العين فى الموعد المحدد لعودته للإقامة بالجمهورية وبشرط أن يمنح المستأجر أجلا مدته ثلاثة أشهر من تاريخ إخطاره ليقوم بإخلاء العين وردها إلى مالكها ، وإلا اعتبر شاغلا للعين دون سند قانونى وذلك أيا كانت مدة الإيجار المتفق عليها .$m247$,'2f76821a91aff991d9147d3eaf5bb99c',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(40,0,1,$m247$لا يجوز للمستأجر فى غير المصايف والمشاتى المحددة وفقا لأحكام هذا القانون أن يؤجر المكان المؤجر له مفروشا أو خاليا إلا فى الحالات الآتية :
(أ) إذا أقام خارج الجمهورية بصفة مؤقتة :
وعلى المستأجر الأصلى فى هذه الحالة أن يخطر المستأجر من الباطن لإخلاء العين فى الموعد المحدد لعودته للإقامة بالجمهورية ، بشرط أن يمنح المستأجر من الباطن أجلا مدته ثلاثة أشهر من تاريخ إخطاره ليقوم بإخلاء العين وردها إلى المستأجر الأصلى وإلا اعتبر شاغلا للعين دون سند قانونى ، وذلك أيا كانت مدة الإيجار المتفق عليه .
(ب) إذا كان مزاولا لمهنة حرة أو حرفة غير مقلقة للراحة أو مضرة بالصحة وأجر جزءا من المكان المؤجر له لهذا الغرض إلى من يمارس مهنة أو حرفة ولو كانت مغايرة لمهنته أو حرفته .
(ج) إذا أجر المكان المؤجر له كله أو جزءا منه للطلاب الذين يدرسون فى غير المدن التى تقيم فيها أسرهم .
(د) التأجير للعمال فى مناطق تجمعاتهم ، وكذا التأجير للعاملين بمختلف أجهزة الدولة والحكم المحلى والقطاع العام وذلك فى المدن التى يعينون بها أو ينقلون إليها .
(هـ) فى الحالات والشروط المبينة بالبندين (أ ، ب) من المادة السابقة .
وفى جميع الأحوال يشترط ألا يزيد مجموع ما يقوم المستأجر هو وزوجته وأولاده القصر بتأجيره مفروشا على شقة واحدة فى نفس المدينة .
ولا يقيد من حكم هذه المادة سوى مستأجرى وحدات الأماكن الخالية .$m247$,'f3c34fa5c9d96bea76bee5861d03f5c7',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(41,0,1,$m247$فيما عدا الفنادق والنزل يجب على كل من أجر مكانا مفروشا أو جزءا منه أو آوى أو أسكن أى أجنبى أو مصرى ، أن يخطر قسم الشرطة الذى يتبعه المكان باسم الشاغل للمكان وجنسيته ورقم جواز سفره إن كان أجنبيا ورقم ومكان وتاريخ صدور بطاقته الشخصية أو العائلية إن كان مصريا ، ومدة الإيجار أو الإشغال والغرض منه وتاريخ بداية هذه المدة ونهايتها ، وذلك خلال ثلاثة أيام من تاريخ تأجير أو شغل المكان أيهما أسبق .$m247$,'c2c9362d4e58a22dfe4b5ff2dbf043a7',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(42,0,1,$m247$على المؤجر أن يطلب قيد عقود الإيجار المفروش التى تبرم تطبيقا لأحكام المادتين 39 ، 40 لدى الوحدة المحلية المختصة وتلزم هذه الجهة بإخطار مصلحة الضرائب شهريا بما تجمع لديها من بيانات فى هذا الشأن .$m247$,'bb5a8b09fbab6a68b6e60e4b14c3ade2',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(43,0,1,$m247$لا تسمع دعاوى المؤجر كما لا تقبل الطلبات المقدمة منه الناشئة أو المترتبة على تطبيق أحكام المادتين 39 ، 40 إلا إذا كانت العقود المبرمة وفقا لها مقيدة على الوجه المنصوص عليه فى المادة السابقة .
ولا يجوز للمؤجر الاستناد إلى العقود غير المقيدة لدى أية جهة من الجهات .$m247$,'668b27854f0c99f6ac84907f8fda890b',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(44,0,1,$m247$مع عدم الإخلال بأحكام المادتين 39 ، 40 يجوز للملاك ولمستأجرى الأماكن الخالية فى المصايف والمشاتى التى يصدر بتحديدها قرار من وزير الإسكان والتعمير بعد أخذ رأى المحافظ المختص ، تأجير الأماكن مفروشة طبقا للشروط والأوضاع التى ينص عليها هذا القرار .$m247$,'bc59532d0d384e8d70a301475b38130a',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(45,0,1,$m247$فى جميع الأحوال التى يجوز فيها للمستأجر تأجير المكان أو جزء من المكان المؤجر مفروشا يستحق المالك أجرة إضافية عن مدة التأجير مفروشا بواقع نسبة من الأجرة القانونية تحسب على الوجه الآتى :
(أ) أربعمائة فى المائة (400%) عن الأماكن المنشأة قبل أول يناير سنة 1944
(ب) مائتان فى المائة (200%) عن الأماكن المنشأة منذ أول يناير سنة 1944 وقبل 5 نوفمبر سنة 1961
(ج) مائة وخمسون فى المائة (150%) عن الأماكن المنشأة منذ 5 نوفمبر سنة 1961 حتى تاريخ العمل بهذا القانون .
(د) مائة فى المائة (100%) عن الأماكن التى يرخص فى إقامتها اعتبارا من تاريخ العمل بأحكام هذا القانون .
وفى حالة تأجير المكان المفروش جزئيا يستحق المالك نصف النسب الموضحة فى هذه المادة .$m247$,'38beb2b1426d187d2434516aaf23421e',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(46,0,1,$m247$يحق للمستأجر الذى يسكن فى عين استأجرها مفروشة من مالكها لمدة خمس سنوات متصلة سابقة على تاريخ العمل بهذا القانون البقاء فى العين ولو انتهت المدة المتفق عليها وذلك بالشروط المنصوص عليها فى العقد ، ولا يجوز للمؤجر طلب إخلائه إلا إذا كان أجرها بسبب إقامته فى الخارج وثبتت عودته نهائيا أو إذا أخل المستأجر بأحد التزاماته وفقا لأحكام البنود (أ ، ب ، ج ، د) من المادة 31 من هذا القانون .
فإذا كانت العين قد أجرت مفروشة من مستأجرها الأصلى فإنه يشترط لاستفادة المستأجر من الباطن من حكم الفقرة السابقة أن يكون قد أمضى فى العين مدة عشر سنوات متصلة سابقة على تاريخ العمل بهذا القانون .$m247$,'2074850bb2c3e023c3e1e3dffa11564f',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(47,0,1,$m247$فى غير الحالات المنصوص عليها فى المادة السابقة ، يجب على الملاك والمستأجرين المؤجرين لأماكن مفروشة حتى تاريخ العمل بهذا القانون تعديل الأوضاع وفقا لأحكام هذا الفصل خلال ستة أشهر من ذلك التاريخ أو انتهاء مدد العقود أيهما أقرب ويسلم المكان إلى المالك أو المستأجر الأصلى بحسب الأحوال ، ويجوز لمجلس الوزراء لاعتبارات المصلحة العامة التى يراها أن يمد هذه المهلة لمدة أو لمدد لا تجاوز سنتين من تاريخ العمل بهذا القانون .$m247$,'c99296204531877da8e8e373dfe30903',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(48,0,1,$m247$لا يفيد من أحكام هذا الفصل سوى الملاك والمستأجرين المصريين .
على ألا تسرى أحكام الفصلين الثانى والرابع من الباب الأول وكذا أحكام الفصل الأول من الباب الرابع من هذا القانون على مشروعات الإسكان والامتداد العمرانى التى تقام وفقا لأحكام القانون المنظم لاستثمار المال العربى والأجنبى والمناطق الحرة$m247$,'e1b35031aa72ffb1c48d296ab4458bc7',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(49,0,1,$m247$يجوز لمالك المبنى المؤجرة كل وحداته لغير أغراض السكن ، أن ينبه على المستأجرين بإعلان على يد محضر بإخلاء المبنى بقصد إعادة بنائه وزيادة مسطحاته وعدد وحداته وذلك وفقا للشروط والأوضاع الآتية :
(أ) أن يحصل المالك على التصاريح والتراخيص والمواصفات اللازمة للهدم وإعادة البناء وفقا لأحكام القانون على أن يتضمن الترخيص بناء وحدات جديدة تصلح لذات الغرض الذى كانت تستعمل فيه الوحدات المرخص بهدمها .
(ب) ألا تقل جملة مسطحات أدوار المبنى الجديد عن أربعة أمثال مسطحات أدوار المبنى قبل الهدم .
(ج) أن يشتمل المبنى الجديد على وحدات سكنية أو فندقية لا يقل مجموع مسطحاتها عن خمسين فى المائة (50%) من مجموع مسطحاته .
(د) أن يقوم المالك بتوفير وحدة مناسبة بأجر مماثل ليمارس المستأجر نشاطه فيها وإلا التزم بتعويضه بمبلغ مساو للفرق بين القيمة الإيجارية للوحدة التى يشغلها والقيمة الإيجارية للوحدة التى يتعاقد على ممارسة نشاطه فيها لمدة خمس سنوات أو للمدة التى تنقضى إلى أن يعود إلى المكان ببنائه بذات القيمة الإيجارية الأولى ، أو يدفع مبلغا مساويا للقيمة الإيجارية للوحدة التى يشغلها خالية عن مدة عشر سنوات بحد أدنى قدره ألفا جنيه أيهما أكبر .
(هـ) أن يحدد المالك موعدا يتم فيه الإخلاء على ألا يكون هذا الموعد قبل انقضاء أطول مدة إيجار متفق عليها عن أى وحدة من وحدات المبنى وبشرط ألا يقل عن ستة أشهر من تاريخ التنبيه بالإخلاء .$m247$,'c8d7182e6c23bd7fdebd1c1bea42b81f',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(50,0,1,$m247$لا يلتزم المستأجرون بالإخلاء إلا بموافقتهم جميعا عليه وذلك بموجب خطابات للمالك موصى عليها مصحوبة بعلم الوصول أو بإقرارات كتابية منهم .
فإذا انقضت ثلاثة أشهر على التنبيه بالإخلاء دون موافقة جميع المستأجرين عليه جاز للمالك أن يلجأ إلى المحكمة المختصة للحصول على حكم بالإخلاء ، ويكون هذا الحكم قابلا للتنفيذ بعد انقضاء ثلاثة أشهر من تاريخ النطق به ، ويشترط أداء التعويض المنصوص عليه فى المادة السابقة أو إيداعه المحكمة المختصة إيداعا غير مشروط لصالح المستأجرين .
وإذا امتنع أى من المستأجرين عن تنفيذ الإخلاء فى الموعد المحدد بالتنبيه المعلن إليهم من المالك بعد موافقة جميع المستأجرين أو بناء على حكم المحكمة المختصة وقيام المالك بأداء التعويض المستحق ، جاز للمالك أن يستصدر من قاضى الأمور المستعجلة حكما بطرد الممتنع عن الإخلاء فورا .$m247$,'a8bbca3c25537183def5b7468f2d2cb0',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(51,0,1,$m247$لا تسرى أحكام هذا الفصل على المبانى المؤجرة لاستعمالها دورا للتعليم حكومية أو خاصة تخضع للإشراف الحكومى وكذلك المستشفيات العامة أو الخاصة الخاضعة لإشراف وزارة الصحة ومحطات تموين وخدمة السيارات أو المنشآت السياحية أو الفندقية أو المصرفية وغيرها من المنشآت ذات الأهمية للاقتصاد أو الأمن القومى أو التى تقدم خدمات عامة للجمهور والتى يصدر بتحديدها قرار من وزير الإسكان والتعمير بعد موافقة الوزير المختص .
أما غير ذلك من المبانى المؤجرة للجهات الحكومية أو لوحدات الحكم المحلى أو للهيئات العامة أو لوحدات القطاع العام فتسرى عليها أحكام هذا الفصل على أن تزاد المهلة بالنسبة إليها إلى ثلاث سنوات من تاريخ التنبيه بالإخلاء إذا طلبت الجهة المستأجرة الإفادة من هذه المهلة وذلك مقابل التنازل عن تعويض الإخلاء .$m247$,'0a504a0743119c416b6ea3833a2e9952',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(52,0,1,$m247$على المالك أو خلفه العام أو الخاص أن يتم الهدم فى مدة أقصاها ثلاثة أشهر من تاريخ إخلاء المبنى كله ، وأن يشرع فى إعادة البناء خلال ثلاثة أشهر من تاريخ انتهاء الهدم .
فإذا لم يتم الهدم خلال المدة المشار إليها دون عذر مقبول كان لمن يرغب من المستأجرين بحكم من قاضى الأمور المستعجلة الحق فى العودة إلى شغل وحدته متى كان ذلك ممكنا ، وإلا كان له الحق فى تعويض قانونى مماثل للتعويض المنصوص عليه فى المادة (49) بالإضافة إلى حقه فى الاحتفاظ بالتعويض الذى تقاضاه من المالك عند موافقته على الإخلاء ، وذلك كله دون إخلال بحقه فى المطالبة قضاء بما يزيد على هذا التعويض إن كان له مقتض .$m247$,'2af7a5259760b80d2f7aafcede2a6b41',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(53,0,1,$m247$إذا تم الهدم ولم يشرع المالك أو خلفه فى البناء خلال المدة المشار إليها فى المادة السابقة ، أو شرع فى البناء ثم تعمد عدم إتمامه فى الوقت الذى تحدده الجهة المختصة بشئون التنظيم جاز للمحافظ المختص أن يعهد إلى إحدى الجهات القيام بالبناء أو تكملته على حساب المالك وفقا للقواعد التى يصدر بها قرار من وزير الإسكان والتعمير ويكون للمبالغ المستحقة لهذه الجهة حق امتياز على المبنى الذى قامت بإنشائه أو استكماله من ذات مرتبة الامتياز المقرر للمبالغ المستحقة للمقاولين والمهندسين المعماريين طبقا لنص المادة (1148) من القانون المدنى .
ويكون للجهة المشار إليها تأجير المبنى واقتضاء أجرته إلى أن تستوفى المبالغ التى أنفقتها والمصروفات الإدارية ، ويحق للمالك أن يحصل على 20% من تلك الأجرة شهريا .$m247$,'fe42477289d8716f6626fbbdf3a4f77d',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(54,0,1,$m247$لمستأجرى الوحدات التى يتم هدمها وفقا لأحكام هذا الفصل الحق فى شغل الوحدات بالعقار الجديد الذى أعيد بناؤه ويلتزم المالك أو خلفه العام أو الخاص بإنشاء وحدات جديدة تصلح لذات الغرض الذى كانت تستعمل فيه الوحدات المهدومة ما لم تحل التشريعات السارية دون ذلك . وفى هذه الحالة يستحق المستأجر تعويضا آخر مساو للتعويض المنصوص عليه فى المادة 49 من هذا القانون .
ويلتزم المالك بإخطار مستأجرى وحدات العقار المهدوم بإتمام إعادة البناء بإنذار على يد محضر ، يرسل إليهم على محال إقامتهم التى يخطرون بها المالك عند الإخلاء ، وذلك خلال مدة لا تجاوز شهرا من تاريخ إتمام البناء .
وعلى المستأجر إبداء رغبته بكتاب موصى عليه مصحوب بعلم الوصول فى شغل وحدة فى العقار المنشأ فى مدة لا تجاوز شهرين من تاريخ إخطاره وإلا سقط حقه فى ذلك .
وتحدد بقرار من وزير الإسكان والتعمير قواعد وإجراءات وأولويات شغل مستأجرى العقار المهدوم لوحدات المبنى الجديد .$m247$,'85482fb1638b6d12e6cba8ca54836ecd',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(55,0,1,$m247$تسرى أحكام هذا الفصل على المبانى والمنشآت التى يخشى من سقوطها أو سقوط جزء منها مما يعرض الأرواح والأموال للخطر ، كما تسرى على المنشآت المشار إليها إذا كانت تحتاج إلى ترميم أو صيانة لتأمين سلامتها أو للحفاظ عليها فى حالة جيدة .
وتبين القرارات التى يصدرها وزير الإسكان والتعمير الأعمال التى تعتبر من أعمال الترميم والصيانة وحدودها فى تطبيق أحكام هذا الفصل .$m247$,'c9a907eaf47966aff6356d6a926f0525',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(56,0,1,$m247$تتولى الجهة الإدارية المختصة بشئون التنظيم معاينة وفحص المبانى والمنشآت وتقرر ما يلزم اتخاذه للمحافظة على الأرواح والأموال سواء بالهدم الكلى أو الجزئى أو التدعيم أو الترميم أو الصيانة لجعلها صالحة للغرض المخصصة من أجله .
ويتضمن القرار تحديد المدة اللازمة لتنفيذ الأعمال المطلوبة وما إذا كانت تستوجب إخلاء المبنى مؤقتا كليا أو جزئيا .$m247$,'05d6bbd2568d56aaf6b4f1df14cd2f85',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(57,0,1,$m247$تشكل فى كل وحدة من وحدات الحكم المحلى ، لجنة أو أكثر يصدر بها قرار من المحافظ المختص ، تضم اثنين من المهندسين المعماريين أو المدنيين المقيدين بنقابة المهندسين ، تتولى دراسة التقارير المقدمة من الجهة الإدارية المختصة بشئون التنظيم فى شأن المبانى المشار إليها فى المادة (55) وإجراء المعاينات على الطبيعة ، وإصدار قرارات فى شأنها على وجه السرعة .
ويبين القرار الذى يصدره وزير الإسكان والتعمير كيفية تشكيل تلك اللجان والقواعد والإجراءات التى تتبع فى مزاولة أعمالها .$m247$,'8b3093b01b1f346f1fea5a3e73fd5158',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(58,0,1,$m247$يعلن قرار اللجنة بالطريق الإدارى إلى ذوى الشأن من الملاك وشاغلى العقار وأصحاب الحقوق وتعاد صورة منه إلى الجهة الإدارية المختصة بشئون التنظيم ، فإذا لم يتيسر إعلانهم بسبب غيبتهم غيبة منقطعة أو لعدم الاستدلال على محال إقامتهم أو لامتناعهم عن تسلم الإعلان تلصق نسخة من القرار فى مكان ظاهر بواجهة العقار وفى لوحة الإعلانات فى مقر نقطة الشرطة الواقع فى دائرتها العقار وفى مقر عمدة الناحية ولوحة الإعلانات فى مقر المجلس المحلى المختص بحسب الأحوال .
وتتبع الطريقة ذاتها فى إعلان القرارات الخاصة بالمنشآت التى لم يستدل على ذوى الشأن فيها .$m247$,'4d4acd365ef17201aa91dc62ab11c42c',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(59,0,1,$m247$لكل من ذوى الشأن أن يطعن فى القرار المشار إليه بالمادة السابقة فى موعد لا يجاوز خمسة عشر يوما من تاريخ إعلانه بالقرار ، أمام المحكمة المنصوص عليها فى المادة (18) من هذا القانون .
وعلى قلم كتاب المحكمة إعلان الجهة الإدارية القائمة على شئون التنظيم وذوى الشأن من ملاك العقارات وأصحاب الحقوق بالطعن فى قرار اللجنة وبالجلسة المحددة لنظر هذا الطعن .
وتفصل المحكمة على وجه السرعة إما برفض الطعن أو بقبوله وإعادة النظر فى القرار المطعون عليه ، وعليها فى حالة الحكم بالهدم الكلى أو الجزئى أو التدعيم أو الترميم أو الصيانة أن تحدد أجلا لتنفيذ حكمها .$m247$,'1629efc3502fcdf1177b3cf6ad09af89',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(60,0,1,$m247$مع عدم الإخلال بالأحكام الخاصة بتوجيه وتنظيم أعمال البناء ، يجب على ذوى الشأن أن يبادروا إلى تنفيذ قرار اللجنة النهائى أو حكم المحكمة الصادر فى شأن المنشآت الآيلة للسقوط والترميم والصيانة وفقا لأحكام هذا القانون ، وذلك فى المدة المحددة لتنفيذه .
وللجهة الإدارية المختصة بشئون التنظيم فى حالة امتناع ذوى الشأن عن تنفيذ قرار اللجنة النهائى أو حكم المحكمة بحسب الأحوال فى المدة المحددة لذلك ، أن تقوم بتنفيذه على نفقة صاحب الشأن وتحصل قيمة التكاليف وجميع النفقات بطريق الحجز الإدارى .
ويجوز للمستأجر إذا تأخر كل من ذوى الشأن والجهة الإدارية المذكورة عن القيام بتنفيذ ما نص عليه القرار النهائى أو قضى به حكم المحكمة بحسب الأحوال ، أن يحصل على إذن من القضاء المستعجل فى أن يجرى الأعمال المقررة دون حاجة إلى الحصول على موافقة المالك ، وأن يستوفى ما أنفقه خصما من مستحقات المالك لديه .$m247$,'afc0f718764faf33799b10eeb9f6bbfd',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(61,0,1,$m247$على كل من المالك والمستأجر فور إتمام أعمال الترميم أو الصيانة إخطار الجهة الإدارية المختصة بشئون التنظيم على أن يتضمن إخطاره طلب اعتماد المبالغ التى أنفقت وذلك وفقا لما تحدده اللائحة التنفيذية .
وعلى الجهة الإدارية المذكورة أن تبت فى الطلب وتخطر كلا من الملاك والمستأجرين بقرارها فى هذا الشأن خلال ثلاثة أسابيع .
وبمجرد إبلاغ الجهة الإدارية القرار المذكور إلى المالك يكون من حقه تقاضى الأجرة اعتبارا من أول الشهر التالى لإتمام الأعمال المشار إليها على أساس زيادة الأجرة السنوية بمقدار 20% (عشرون فى المائة) من قيمة أعمال الترميم والصيانة ، وتتبع أحكام زيادة الأجرة المنصوص عليها فى هذه الفقرة فى الحالات التى يتم فيها إجراء الترميم أو الصيانة بناء على اتفاق صريح كتابى بين المالك والمستأجر .
ويترتب على عدم سداد هذه الزيادة ما يترتب على عدم سداد الأجرة من آثار .$m247$,'f04b7468acf37584fd45a9b7dd6fedfc',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(62,0,1,$m247$يجوز لوزارة الإسكان والتعمير والأجهزة التابعة لها ووحدات الحكم المحلى والمصارف أن تقرض بشروط ميسرة ملاك المبانى أو شاغليها الخاضعة لأحكام هذا القانون للقيام بترميمها وصيانتها .
ويصدر بشروط وقواعد الإقراض قرار من وزير الإسكان والتعمير بعد الاتفاق مع وزير المالية .
وتعفى القروض من جميع الضرائب والرسوم وتحصل بطريق الحجز الإدارى .
ويكون للقروض امتياز على العين التى تم ترميمها أو صيانتها يجىء فى الترتيب مع الامتياز المقرر فى القانون المدنى للمقاولين والمهندسين .$m247$,'88c59f12cf120ebe6c812d9804919a18',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(63,0,1,$m247$إذا اقتضت أعمال الترميم أو الصيانة إخلاء المبنى مؤقتا من شاغليه حرر محضر إدارى بأسماء المستأجرين للقاطنين دون سواهم ، وتقوم الجهة الإدارية المختصة بشئون التنظيم بإخطارهم بالإخلاء فى المدة التى تحددها وإذا لم يتم الإخلاء بعد انقضائها جاز تنفيذه بالطريق الإدارى ولشاغلى العين الحق فى العودة إلى العين بعد ترميمها دون حاجة إلى موافقة المالك ، ويتم ذلك بالطريق الإدارى فى حالة امتناع المالك .
وتضاف الأجرة خلال فترة الإخلاء إلى تكاليف الإصلاح اللازمة لتنفيذ أعمال الترميم والصيانة التى تحددها الجهة الإدارية المختصة .
ولا يجوز مد هذه المدة إلا بقرار من الجهة المذكورة ، وفى هذه الحالة يجوز لشاغل العين التظلم من القرار أمام رئيس المحكمة المنصوص عليها فى المادة 18 من هذا القانون .
وتعتبر العين خلال هذه المدة فى حيازة المستأجر قانونا ولا يجوز للمالك أن يغير فى معالم العين كل ذلك ما لم يبد المستأجر رغبته فى إنهاء العقد خلال خمسة عشر يوما من تاريخ إخطاره بقرار الإخلاء المؤقت .$m247$,'b8d7f0732da00393ae0da09f622713ca',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(64,0,1,$m247$على شاغلى العين الصادر قرار أو حكم نهائى بهدمها أن يبادروا إلى إخلائها فى المدة المحددة فى الحكم أو القرار فإذا امتنعوا عن الإخلاء كان للجهة الإدارية المختصة بشئون التنظيم إخلاؤهم بالطريق الإدارى وعلى نفقتهم دون أية إجراءات .$m247$,'ccfd0d8af45dcde0c18d51e7a2283c24',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(65,0,1,$m247$يجوز للجهة الإدارية المختصة بشئون التنظيم فى أحوال الخطر الداهم إخلاء البناء وكذلك المبانى المجاورة عند الضرورة من السكان بالطريق الإدارى واتخاذ ما تراه لازما من الاحتياطات والتدابير فى مدة لا تقل عن أسبوع إلا فى حالة تهديد البناء بالانهيار العاجل فيكون لها فى هذه الحالة الحق فى إخلائه فورا .
كما يكون لها فى حالة الضرورة القصوى هدم البناء بموجب حكم من قاضى الأمور المستعجلة بالمحكمة الكائن فى دائرتها العقار .$m247$,'fac79af5b9fe99e1a089dbc924e2bde7',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(66,0,1,$m247$مع عدم الإخلال بأحكام القانون رقم 169 لسنة 1961 بتقرير بعض الإعفاءات الضريبية على العقارات المبنية وخفض الإيجارات بمقدار الإعفاء والقانون رقم 38 لسنة 1967 فى شأن النظافة العامة ، والقانون رقم 46 لسنة 1968 باستثناء بعض الأماكن من الإعفاءات الضريبية المقررة بالقانون رقم 169 لسنة 1961 المشار إليه ، يعفى شاغلو المساكن من أداء الضرائب العقارية الأصلية والإضافية إذا زاد متوسط الإيجار الشهرى للغرفة الواحدة فيها على ثلاثة جنيهات ولم يجاوز خمسة جنيهات .
كما يعفى شاغلو المساكن من أداء الضريبة الأصلية دون الضرائب الإضافية وذلك إذا زاد متوسط الإيجار الشهرى للغرفة الواحدة فيها على خمسة جنيهات ولم يجاوز ثمانية جنيهات .
كما يعفى أصحاب العقارات التى أنشئت قبل أول يناير سنة 1944 من ضرائب الدفاع والأمن القومى .$m247$,'d9e96787b344ca375358dfc2a52094ac',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(67,0,1,$m247$تسرى الإعفاءات المقررة بالمادة السابقة اعتبارا من أول يناير سنة 1977 على المساكن المنشأة أو المشغولة لأول مرة بعد 18/8/1969 ، وعلى لجان تقدير الإيجارات والمحكمة المختصة مراعاة ذلك عند تقدير الأجرة وفقا لأحكام هذا القانون .
على أنه بالنسبة إلى المساكن المنشأة أو المشغولة لأول مرة منذ تاريخ العمل بهذا القانون يعفى شاغلو المساكن من أداء الضرائب العقارية الأصلية والإضافية إذا لم يجاوز متوسط الإيجار الشهرى للغرفة الواحدة فيها ثمانية جنيهات ، أما إذا زاد المتوسط عن ذلك ولم يجاوز عشرة جنيهات شهريا فيعفى شاغلو المساكن من أداء الضرائب الأصلية دون الضرائب الإضافية .$m247$,'8c15163ecf515d937357ef185ec23f21',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(68,0,1,$m247$يجوز لأجهزة الدولة ووحدات الحكم المحلى وشركات القطاع العام والجمعيات التعاونية لبناء المساكن وصناديق التأمين الخاصة والشركات الخاصة والأفراد إنشاء المبانى بقصد تمليك كل أو بعض وحداتها السكنية .
ويحظر على الجهات القائمة على منح موافقات وتراخيص البناء ، التصريح للشركات الخاصة والأفراد بإقامة مبان أو أجزاء منها بقصد التمليك إلا فى حدود عشرة فى المائة (10%) من جملة الاستثمارات المقررة لكل مستوى من مستويات الإسكان المختلفة ، ويصدر قرار من وزير الإسكان والتعمير بقواعد الأولوية فى حدود هذه النسبة .
ويلتزم كل من البائع والمشترى فى حالة التعاقد بأن يكتتب بـ 5% من ثمن البيع فى شراء سندات لصالح صندوق تمويل مشروعات الإسكان الاقتصادى وذلك دون الإخلال بأية التزامات أخرى يفرضها القانون رقم 107 لسنة 1976 .$m247$,'083408bb4c862e359bf53cdc9448db57',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(69,0,1,$m247$يجب أن يرفق بمستندات طلب الموافقة أو الترخيص بالبناء بيان موقع من المالك أو من ينيبه يبين فيه ما إذا كان البناء كله أو بعضه بقصد التمليك أو التأجير ، وإذا صدرت الموافقة أو الترخيص بالبناء على أساس تأجير المبنى كله أو بعضه وجب على الطالب أن يقوم بتأجير عدد من الوحدات لا يقل عن العدد الذى صدرت الموافقة بالترخيص بالبناء على أساسه وذلك دون إخلال بحق المالك فى التصرف فى العقار كله أو بعضه وفقا للقواعد العامة .$m247$,'97d619d349c2ace783290fd8b8a9039c',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(70,0,1,$m247$يحظر على المرخص لهم بإقامة مبان أو أجزاء منها بقصد التمليك الاستفادة من النظم أو الميزات الخاصة بتوزيع أو صرف أو تيسير الحصول على مواد البناء وذلك فى حدود ما رخص لهم فى إنشائه بقصد التمليك .
ويتولى ملاك هذه المبانى بمعرفتهم وعلى نفقتهم استيراد ما يلزم لها من مواد البناء ، أو شرائها من المواد المستوردة ، أو من المواد المنتجة محليا بالأسعار العالمية وذلك بعد الوفاء باحتياجات الإسكان المخصص للتأجير .
ويستثنى من ذلك أجهزة الدولة وشركات القطاع العام والجمعيات التعاونية وصناديق التأمين الخاصة .$m247$,'fdc19ec002a017f530b2c8def8010c7f',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(71,0,1,$m247$يحظر على كل من تعاقد على تمليك أو تأجير وحدات سكنية قبل العمل بهذا القانون أو تعاقد على ذلك بعد العمل به أن يتراخى عمدا عن استكمال الوحدات المبيعة أو المؤجرة فى المواعيد المتفق عليها أو يعمد إلى تعطيل الانتفاع بها واستعمالها فيما أعدت له من أغراض .$m247$,'a6ad809f7628a9cd93633bb1721818e8',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(72,0,1,$m247$تملك المساكن الشعبية الاقتصادية والمتوسطة التى أقامتها المحافظات وتم شغلها قبل تاريخ العمل بهذا القانون ، نظير أجرة تقل عن الأجرة القانونية ، إلى مستأجريها على أساس سداد الأجرة المخفضة لمدة خمس عشرة سنة وذلك وفقا للقواعد والشروط والأوضاع التى يصدر بها قرار من رئيس مجلس الوزراء .$m247$,'bc9d89d6eb0d3489e8b576e9aab9f504',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(73,0,1,$m247$إذا زادت طبقات المبنى أو شققه على خمس وجاوز عدد ملاكها خمسة أشخاص قام بقوة القانون اتحاد الملاك المنصوص عليه فى المادة (862) من القانون المدنى وفى تطبيق هذا الحكم يعتبر ملاك الطبقة أو الشقة الواحدة مالكا واحدا ولو تعددوا .
ويكون البائع للعقار بالتقسيط عضوا فى الاتحاد حتى تمام الوفاء بكامل أقساط الثمن ، كما يكون المشترى بعقد غير مسجل عضوا فى الاتحاد .$m247$,'664a59d185bfd003cd6c812ada201add',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(74,0,1,$m247$يصدر وزير الإسكان والتعمير بقرار منه نظاما نموذجيا لاتحادات ملاك العقارات لضمان الانتفاع بالأجزاء المشتركة بالعقار وحسن إدارتها .
ويتضمن النظام كيفية سير العمل بالاتحاد وقواعد تحديد التزامات وواجبات أعضائه وتنظيم استعمالهم لحقوقهم ، وقواعد تمثيل ملاك الطبقة أو الشقة أو بائع العقار إذا تعددوا وبيان أحوال استحقاق أجر مأمور الاتحاد وقواعد تحديده .
وعلى اتحادات ملاك العقارات القائمة وقت العمل بهذا القانون أن تعدل أوضاعها بما يتفق مع أحكامه وذلك خلال ستة أشهر من تاريخ العمل بالقرار المشار إليه فى هذه المادة .
ويسرى حكم الفقرة السابقة على المبانى القائمة التى لم يتكون بها اتحادات ملاك العقارات والتى تتوافر فيها الشروط المنصوص عليها فى المادة السابقة .$m247$,'3d59b868d947ecdd9a6903651ea33edc',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(75,0,1,$m247$تتولى الوحدة المحلية المختصة مراقبة قيام الاتحادات المبينة فى هذا القانون ، والإشراف على أعمالها ويكون لها على الأخص ما يلى :
(أ) قيد الاتحاد وبيان أسماء أعضائه وممثله القانونى .
(ب) دعوة الاتحاد إلى الاجتماع لمباشرة أعماله .
(ج) تعيين مأمور مؤقت للاتحاد إلى أن يتم اختياره أو تعيينه وفقا لأحكام القانون المدنى .
(د) منح المأمور كل أو بعض سلطات الاتحاد إذا قصر أو تراخى فى القيام بواجباته .
(هـ) فحص الشكاوى والتظلمات التى تقدم من ذوى الشأن فى قرارات الاتحاد أو تصرفات المأمور وإبداء الرأى للاتحاد فى شأنها لإعادة النظر فيها إذا اقتضى الأمر ذلك .$m247$,'2f4ab71e89b8b336a194eb58c3fc0df6',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(76,0,1,$m247$يعاقب بالحبس مدة لا تقل عن شهر ولا تزيد على ستة أشهر وبغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين كل من يخالف أحكام المواد 7/1 ، 8 ، 13 ، 24/1 ، 25 من هذا القانون .
ويحكم فضلا عن ذلك فى حالة مخالفة حكم المادة (8/1) بإنهاء عقد المسكن أو المساكن المحتجزة بالمخالفة لحكم القانون .$m247$,'fe64f7586c07726e7bc8a2b8e9dde670',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(77,0,1,$m247$يعاقب كل من يخالف حكم المادة 26 من هذا القانون سواء كان مؤجرا أو مستأجرا أو وسيطا بالحبس مدة لا تقل عن ثلاثة أشهر وبغرامة تعادل مثلى المبلغ الذى تقاضاه بالمخالفة لأحكام هذه المادة ، ويعفى من العقوبة كل من المستأجر والوسيط إذا أبلغ أو بادر بالاعتراف بالجريمة .
وفى جميع الأحوال يجب الحكم على المخالف بأن يرد إلى صاحب الشأن ما تقاضاه على خلاف أحكام المادة المشار إليها .$m247$,'ff3d13ccc12e35a76de59fee8d40131f',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(78,0,1,$m247$يعاقب بالحبس مدة لا تقل عن شهر وبغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين كل من خالف أحكام المواد 39 ، 40 ، 41 من هذا القانون .
وتكون العقوبة الحبس مدة لا تقل عن شهر ولا تجاوز ستة أشهر وبغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين فى حالة مخالفة أحكام المواد 38 ، 52/1 ، 53/1 ، 54/1 ، 54/2 من هذا القانون .$m247$,'9408aa72b10b2e4f9bae120e54954267',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(79,0,1,$m247$يعاقب بالحبس مدة لا تقل عن شهرين ولا تزيد على سنة وبغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين كل من خالف أحكام المادتين 60/1 ، 64 من هذا القانون ، فإذا ترتب على عدم تنفيذ المالك لقرار صادر بالهدم الكلى أو الجزئى سقوط المبنى كانت العقوبة الحبس .$m247$,'8bf9d0c47a12a104adf52c3c35f34b5f',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(80,0,1,$m247$يعاقب على مخالفة أحكام المواد 3/1 ، 69 ، 70/1 ، 71/1 بالحبس مدة لا تقل عن ثلاثة أشهر ولا تجاوز سنة وبغرامة لا تقل عن مائة جنيه ولا تجاوز خمسمائة جنيه أو بإحدى هاتين العقوبتين .
ويحكم فضلا عن ذلك فى حالة مخالفة المادة 69 بغرامة تعادل التكلفة التقديرية للوحدات المبيعة .
كما يحكم فى حالة مخالفة أحكام المادتين 3/1 ، 70/1 بأن يرد المخالف للدولة مبلغا يماثل ثمن المواد التى حصل عليها بالمخالفة لأحكام هاتين المادتين .$m247$,'88e10e12d5eb16ebaa030f8e1c292ac7',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(81,0,1,$m247$يعاقب بالحبس مدة لا تقل عن شهر وبغرامة لا تقل عن مائة جنيه ولا تجاوز ثلاثمائة جنيه كل من يقوم عمدا بأى فعل من شأنه تهديد سلامة مبنى أو تعريضه للسقوط أو إتلافه كليا أو جزئيا إذا كان ذلك بقصد التوصل إلى اعتباره آيلا للسقوط .$m247$,'67a32dbe8ec0f97e93b45ff41cef5afe',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(82,0,1,$m247$يعاقب بالحبس مدة لا تقل عن ستة أشهر وبغرامة لا تقل عن خمسمائة جنيه ولا تجاوز ألفى جنيه أو بإحدى هاتين العقوبتين ، كل من أجر مكانا أو جزءا منه أو باعه ، ولو بعقد غير مشهر ، أو مكن آخر منه وكان ذلك التأجير أو البيع أو التمكين على خلاف مقتضى عقد سابق ، ولو غير مشهر ، صادر منه أو من نائبه أو من أحد شركائه أو تابعيهم ، ويفترض علم هؤلاء بالعقد السابق الصادر من أيهم .
ويعاقب بالعقوبة السابقة من يسبق إلى وضع يده ، أو يشرع فى ذلك على خلاف مقتضى العقد السابق عليه ، قبل استصدار حكم بأفضليته من القضاء المختص ، ويفترض علم هذا المتعرض بالتعاقد السابق إذا كان زوجا لمن تعاقد معه أو من مكنه ، أو كان من أصوله أو فروعه أو من أقاربه أو أصهاره إلى الدرجة الرابعة .$m247$,'b765539ef0157ffe1f0d951f5d77ee83',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(83,0,1,$m247$لا تخل العقوبات الواردة فى هذا القانون بأية عقوبة أشد منصوص عليها فى أى قانون آخر .$m247$,'f5b5da52433406d2705073c6c822a66a',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(84,0,1,$m247$تؤول حصيلة جميع الغرامات التى يقضى بها تنفيذا لأحكام هذا القانون إلى صندوق تمويل مشروعات الإسكان الاقتصادى .$m247$,'e64645040cf9ffe31d009f9d813a2555',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(85,0,1,$m247$تستمر المحاكم فى نظر الدعاوى التى أقيمت قبل العمل بهذا القانون طبقا للقواعد والإجراءات السارية قبل نفاذه .$m247$,'067938aba3c57f83bd1f9ba359160d3a',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(86,0,1,$m247$يلغى القانون رقم 52 لسنة 1969 وأوامر نائب الحاكم العسكرى العام رقما 4 ، 5 لسنة 1976 ورقم 5 لسنة 1977 ، كما يلغى كل حكم يخالف أحكام هذا القانون .$m247$,'01e7b282a965218ee8a22f3d5535a5a4',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(87,0,1,$m247$يصدر وزير الإسكان والتعمير اللوائح والقرارات اللازمة لتنفيذ هذا القانون خلال ثلاثة أشهر من تاريخ العمل به .$m247$,'319d39b7b3b56ca7a619cf73660c8c89',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$),
(88,0,1,$m247$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به من اليوم التالى لتاريخ نشره .$m247$,'ae1ca224d7e2797691b06d55d9fd8f82',DATE '1977-09-09',NULL,'active',NULL,NULL,$m247$النص الأصلى للقانون كما نشر بالجريدة الرسمية العدد 36 فى 8 سبتمبر 1977 (قراءة بصرية لصورة ممسوحة). لم تُطبَّق عليه التعديلات اللاحقة، فقد لا يطابق النص النافذ حالياً؛ يُراجع على الوقائع المصرية قبل الاستناد إليه.$m247$);

DO $m247$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m247_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m247_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[247] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m247_art) <> 89 OR (SELECT sum(char_length(body)) FROM m247_art) <> 44694 OR (SELECT count(*) FROM m247_ver) <> 89 THEN
    RAISE EXCEPTION '[247] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=49 AND law_year=1977 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%تأجير وبيع الأماكن%' THEN
    RAISE EXCEPTION '[247] يوجد مستند آخر برقم 49 لسنة 1977 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (49, 1977, $t247$القانون رقم 49 لسنة 1977 فى شأن تأجير وبيع الأماكن وتنظيم العلاقة بين المؤجر والمستأجر (النص الأصلى كما نشر بالجريدة الرسمية)$t247$, $t247$قانون إيجار الأماكن 49/1977$t247$, 'other', 'amended', NULL, DATE '1977-08-20', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m247_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m247_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m247_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 89 THEN
    RAISE EXCEPTION '[247] عدد صفوف النص % بدل 89', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 89 THEN
    RAISE EXCEPTION '[247] عدد نسخ النص % بدل 89', v_vcnt;
  END IF;
  RAISE NOTICE '[247] قانون 49/1977: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m247$;
